/* Alarmes et scénarios (leçons, exercices, aléas, TMI) ; l'accompagnement des leçons est dans js/lecons.js. */
'use strict';
/* ================= Alarmes ================= */
const ALM=[
 ['aar','Arrêt automatique réacteur','r',s=>s.tripped],
 ['is','Injection de sécurité','r',s=>s.is],
 ['lim','Limite de sûreté dépassée','r',s=>s.limitNow],
 ['drop','Chute de grappe','r',s=>s.dropped],
 ['gmpp','Pompe primaire déclenchée','r',s=>s.pumps.some(p=>!p)],
 ['sebim','Soupape pressu SEBIM ouverte','r',s=>s.sebim],
 ['mdt','Manque de tension tableaux normaux','r',s=>s.el&&!s.el.src.LG],
 ['lhx','Tableau secouru hors tension','r',s=>s.el&&(!s.el.src.LHA||!s.el.src.LHB)],
 ['dgf','Défaut diesel','r',s=>s.el&&(s.el.dg.A.st==='defaut'||s.el.dg.B.st==='defaut')],
 ['rtb','Groupe R limite très basse','r',s=>!s.tripped&&s.coupled&&s.rods.R.p<130],
 ['rdpd','Disque de rupture du réservoir de décharge pressu rompu','r',s=>s.tmi&&s.rdpBurst],
 ['tc','Thermocouples sortie cœur hors échelle','r',s=>s.tmi&&s.Ttc>371],
 ['hflux','Puissance nucléaire > 103 %','a',s=>s.n>1.03],
 ['per','Temps de doublement < 20 s','a',s=>!s.tripped&&s.Td<20],
 ['dtm','Marge ΔT protection < 5 %','a',s=>!s.tripped&&s.dtMargin<5],
 ['tmh','Tmoy − Tref > +1,5 °C','a',s=>s.coupled&&!s.tripped&&s.Tavg-s.Tref>1.5],
 ['tml','Tmoy − Tref < −1,5 °C','a',s=>s.coupled&&!s.tripped&&s.Tavg-s.Tref<-1.5],
 ['pph','Pression pressu haute','a',s=>s.Ppzr>157.5],
 ['ppl','Pression pressu basse','a',s=>s.Ppzr<152],
 ['lph','Niveau pressu haut','a',s=>s.Lpzr>s.Lref+5],
 ['lpl','Niveau pressu bas','a',s=>s.Lpzr<s.Lref-5],
 ['lgh','Niveau GV haut','a',s=>s.Lsg>60],
 ['lgl','Niveau GV bas','a',s=>s.Lsg<40],
 ['aret','Écart débit ARE / vapeur','a',s=>!s.tripped&&Math.abs(s.Wf+s.Wasg-s.Wst)>0.15],
 ['tpa','Turbopompe alimentaire déclenchée','a',s=>!s.tpa[0]||!s.tpa[1]],
 ['chg','Débit de charge RCV élevé','a',s=>s.Qc>28],
 ['kenc','Activité enceinte élevée (KRT)','a',s=>s.Qleak>0.5||s.tmi&&s.mEnc>0.5],
 ['rlb','Groupe R limite basse','a',s=>!s.tripped&&s.coupled&&s.rods.R.p<150],
 ['di','ΔI hors domaine','a',s=>!s.tripped&&s.n>0.15&&Math.abs(s.DI+1.5*s.n)>5],
 ['sat','Marge à la saturation < 15 °C','a',s=>!s.era79&&s.satMargin<15],
 ['grid','Perte réseau — îlotage','a',s=>s.ilot],
 ['turb','Turbine déclenchée','a',s=>s.turbTripped],
 ['dgs','Diesel en service','a',s=>s.el&&['service','demarrage'].some(x=>x===s.el.dg.A.st||x===s.el.dg.B.st)],
 ['bat','Batteries en décharge','a',s=>s.el&&!s.el.src.LHA&&!s.el.src.LHB],
 ['r225','Réseau 225 kV indisponible','a',s=>s.el&&!s.el.r225],
 ['rlh','Groupe R limite haute','i',s=>!s.tripped&&s.coupled&&s.rods.R.p>215],
 ['gridok','Réseau disponible','i',s=>s.ilot&&s.grid],
 ['rea','Appoint REA en service','i',s=>s.Qdil+s.Qbor>0],
 ['gctc','Contournement GCT-c ouvert','i',s=>s.coupled&&s.gct>0.02],
 ['asg','ASG en service','i',s=>s.asg],
 ['spr','Aspersion pressu ouverte','i',s=>s.spray>0.3],
 ['ldis','Décharge RCV isolée','i',s=>s.Qld===0],
 ['p6','P6 — gamme source à inhiber','i',s=>!s.srInhib&&s.n>1e-7],
 ['p10','P10 — seuil bas haut flux à bloquer','i',s=>s.p10&&!s.lowBlk&&!s.tripped],
 ['tdech','Température ligne de décharge pressu haute','a',s=>s.tmi&&s.Tdech>90],
 ['rdp','Réservoir de décharge pressu : pression haute','a',s=>s.tmi&&s.Prdp>3&&!s.rdpBurst],
 ['penc','Pression enceinte haute','a',s=>s.tmi&&s.Penc>1.05],
 ['vib','Vibrations des pompes primaires','a',s=>s.tmi&&s.vib>0.3],
 ['blk','Blocage extraction grappes','i',s=>!s.tripped&&(s.n>1.03||s.dropped||s.dtMargin<3)],
];
function evalAlarms(s){ let nw=null; const rk={r:0,a:1,i:2};
  for(const [id,lab,sev,f] of ALM){
    let a=s.alarms[id]; if(!a) a=s.alarms[id]={on:false,ack:true};
    const c=!!f(s);
    if(c&&!a.on){ a.on=true; a.ack=false; a.since=s.t; logEv(s,'alarm','Alarme : '+lab); if(nw==null||rk[sev]<rk[nw]) nw=sev; }
    else if(!c&&a.on){ a.on=false; a.ack=true; }
  }
  if(nw&&typeof alarmSound==='function'&&!A.paused) alarmSound(nw);
}

/* ================= Scénarios ================= */
const Cr=(t,ok,d='')=>({t,ok:!!ok,d});
function common(s,c){ return [Cr('Aucune limite de sûreté dépassée',s.limits.size===0,[...s.limits].join(' ; ')),Cr("Pas d'injection de sécurité",c.st.isT==null)]; }
const P100={P:1,xe:1,R:180,G:225,coupled:true,modeR:'auto',modeG:'auto'};
const INTRO_ALEA="<p>La tranche fonctionne de façon stable, régulations en automatique. Un aléa va survenir dans les prochaines minutes. Repérez-le grâce aux alarmes, au synoptique et aux tendances, puis appliquez la conduite adaptée. Si vous êtes bloqué, le bouton <kbd>Indice</kbd> donne jusqu'à trois pistes successives : le symptôme, le système en cause, puis l'action. Seule la dernière retire une étoile.</p>";

const SCN=[
{id:'ihm',kind:'tuto',title:'Prise en main du poste de pilotage',desc:"Le bandeau, le synoptique cliquable, les vues, les commandes, les alarmes, et la façon dont un opérateur surveille sa tranche.",diff:1,speed:1,init:P100,
 next:"<p>Suite conseillée : le <b>Tutoriel de prise de quart</b>, qui utilise ce poste pour piloter le réacteur (grappes, bore, pressuriseur, AAR).</p>",
 brief:"<p>Durée : 10 minutes. La tranche est stable à 100 %, régulations en automatique : rien ne presse. Ce tutoriel ne parle pas de physique, il montre <b>comment le poste fonctionne</b> et <b>comment on surveille</b> une tranche. Chaque étape demande un clic ; le bouton <kbd>Suivant</kbd> s'active quand il est fait.</p>",
 steps:[
 {t:'Le poste en un coup d\'œil',h:"<p>Le poste se lit <b>de haut en bas, du général au détail</b>, comme une salle de commande.</p><ul><li><b>Le bandeau</b>, tout en haut : les grandeurs essentielles de la tranche, toujours visibles.</li><li><b>Le bloc d'attention</b>, sous le bandeau : les <b>alarmes</b> actives, <b>mes actions</b> en cours, les <b>automatismes</b> en service. C'est ce qui demande votre attention maintenant.</li><li><b>La vue centrale</b> : le synoptique de la tranche par défaut, d'autres vues par les onglets du bas.</li><li><b>À droite</b> : cette consigne, puis les <b>commandes</b>, rangées en quatre familles.</li></ul><p>Sur téléphone, les mêmes éléments sont répartis dans les onglets du bas : <b>Surveiller</b>, <b>Agir</b>, <b>Tendances</b>, <b>Suivre</b>.</p>"},
 {t:'Le bandeau : l\'état de la tranche',h:"<p>Le bandeau regroupe les grandeurs en quatre familles de couleur : <b>Cœur</b>, <b>Primaire</b>, <b>Secondaire</b>, <b>Sûreté</b>. Chaque case montre :</p><ul><li>la <b>valeur</b> et son unité, avec une courbe pâle <b>derrière</b> : la tendance des dernières minutes. Une courbe plate est rassurante ; une pente doit vous faire chercher pourquoi ;</li><li>une <b>jauge</b> en bas : le trait est la valeur, la zone claire la plage normale, les repères rouges les seuils ;</li><li>des <b>puces</b> d'état : mode auto ou manuel, appoint en cours, rampe de charge…</li></ul><p>Une case qui sort de sa plage passe en <b>ambre</b>, puis en <b>rouge</b>.</p><p><b>À faire :</b> cliquez sur la case <b>Pression pressu</b>. Chaque case ouvre la carte de commandes qui agit sur cette grandeur.</p>",
  ok:()=>A.uiBand==='pp'},
 {t:'Le synoptique : la tranche en direct',h:"<p>Le synoptique est le plan de la tranche. Les règles de lecture sont simples :</p><ul><li>les équipements sont en <b>gris</b> : la couleur est réservée aux états anormaux ;</li><li>un tuyau en trait plein transporte un débit, un trait <b>pointillé</b> est à l'arrêt ; les tirets qui défilent montrent le sens d'écoulement ;</li><li>chaque étiquette donne une valeur ; elle passe en <b>ambre</b> ou en <b>rouge</b> quand la valeur s'écarte, en <b>bleu</b> quand une action est en cours ;</li><li>une ligne de sauvegarde (ASG, injection de sécurité, soupapes) devient <b>rouge plein</b> dès qu'elle débite.</li></ul><p><b>À faire :</b> cliquez sur le <b>pressuriseur</b> dans le synoptique (le dessin ou une de ses étiquettes).</p>",
  enter:()=>{ if(typeof palClose==='function') palClose(); if(desk()) setVue('synop'); else setTab('synop'); },ok:()=>SY.pal==='pzr'},
 {t:'Agir depuis le synoptique',h:"<p>La fenêtre qui s'est ouverte, ce sont les <b>actions rapides</b> du pressuriseur : quelques valeurs clés et les commandes les plus utiles. Ce sont exactement les mêmes boutons que dans la carte de commandes : agir ici ou là revient au même.</p><p><b>À faire :</b> dans cette fenêtre, mettez les chaufferettes sur <kbd>Forcé</kbd>, regardez l'étiquette « Chauff. · asp. » passer en ambre avec la mention MAN, puis remettez-les sur <kbd>Auto</kbd>.</p><p>Un équipement hors automatique s'affiche toujours en ambre : c'est un rappel, pour ne pas oublier de le remettre en service.</p>",
  enter:(s,c,k)=>{ if(!SY.pal&&typeof palOpen==='function') palOpen('pzr'); },sub:[['Chaufferettes forcées',(s,c,k)=>k.on||(k.on=s.heatMode==='on')],['Retour en auto',(s,c,k)=>k.on&&s.heatMode==='auto']],ok:(s,c,k)=>{ if(s.heatMode==='on') k.on=true; return k.on&&s.heatMode==='auto'; }},
 {t:'Toute la famille de commandes',h:"<p>En bas de la fenêtre d'actions rapides, le lien <kbd>Toute la famille Primaire ›</kbd> ouvre la carte complète, à droite (onglet <b>Agir</b> sur téléphone).</p><p><b>À faire :</b> cliquez sur ce lien. Si vous avez fermé la fenêtre, cliquez de nouveau sur le pressuriseur.</p><p>Le synoptique sert à <b>surveiller et agir vite</b> ; les cartes donnent <b>toutes</b> les commandes et les réglages fins.</p>",
  enter:()=>{ if(desk()) setFam('core'); else setTab('synop'); },ok:()=>!SY.pal&&(desk()?A.fams.includes('prim'):A.tab==='cmd')},
 {t:'Les familles de commandes',h:"<p>Les commandes sont rangées comme le bandeau : <b>Réactivité</b> (grappes, bore), <b>Primaire</b> (pressuriseur, RCV), <b>Secondaire</b> (turbine, eau alimentaire), <b>Sûreté</b> (protections, AAR, injection de sécurité).</p><p>Chaque carte suit le même ordre : en haut les <b>mesures</b>, puis les <b>modes</b> (<kbd>Auto</kbd> / <kbd>Manuel</kbd>), puis les <b>actions</b>. Les boutons à bord ambre (isoler, déclencher) ont des conséquences importantes ; l'AAR et l'injection de sécurité manuels demandent une confirmation. Le « ? » de chaque carte explique ce qu'elle pilote.</p><p><b>À faire :</b> ouvrez la famille <b>Secondaire</b> (onglet <b>Agir</b> sur téléphone).</p>",
  ok:()=>desk()?A.fams.includes('sec'):A.tab==='cmd'},
 {t:'Les vues : changer d\'angle',h:"<p>Les onglets sous la vue centrale changent d'angle sans quitter la tranche des yeux : <b>Courbes</b> (puissance, températures, pression, niveaux sur 5 min, 30 min ou 2 h), <b>ΔI</b> (forme du flux dans le cœur), <b>P-T</b> (le domaine pression-température autorisé), <b>Réactivité</b> (le bilan en pcm), <b>Neutronique</b>, <b>Tendances</b>, <b>Alarmes</b> et <b>Journal</b>. Sur grand écran, les courbes restent sous le synoptique et les alarmes ont leur colonne.</p><p><b>À faire :</b> ouvrez <b>Courbes</b>, regardez, puis revenez au <b>Synoptique</b> (sur téléphone : onglet <b>Tendances</b>, puis <b>Surveiller</b>).</p><p>Le synoptique est la vue de référence : on y revient toujours.</p>",
  enter:(s,c,k)=>{ k.crv=false; },sub:[['Courbes ouvertes',(s,c,k)=>k.crv],['Retour au synoptique',(s,c,k)=>k.crv&&(desk()?A.vues[0]==='synop':A.tab==='synop')]],
  ok:(s,c,k)=>{ if(desk()?A.vues.includes('crv')&&A.vues[0]!=='synop':A.tab==='trend') k.crv=true; return k.crv&&(desk()?A.vues[0]==='synop':A.tab==='synop'); }},
 {t:'Mes actions : suivre ce qu\'on a lancé',h:"<p>Certaines actions durent : une rampe de charge, un appoint en bore. Le bloc <b>Mes actions</b> les affiche avec leur avancement et un bouton pour les arrêter.</p><p><b>À faire :</b> dans le synoptique, cliquez sur l'étiquette <b>Bore</b> (ou <b>RCV</b>). Dans la fenêtre, choisissez <kbd>Borication</kbd>, <kbd>5</kbd> m³/h, <kbd>100 L</kbd>, puis <kbd>Lancer</kbd>.</p><p>Regardez l'appoint apparaître dans <b>Mes actions</b> avec sa barre de progression, l'étiquette « Appoint REA » passer en bleu dans le synoptique, et la puce « Bor. » dans la case Bore du bandeau.</p>",
  enter:()=>{ if(typeof palClose==='function') palClose(); if(desk()) setVue('synop'); else setTab('synop'); },ok:s=>s.rea.run&&s.rea.mode==='bor'},
 {t:'Les alarmes : voir, entendre, acquitter',h:"<p>L'appoint a allumé une <b>information</b> bleue, « Appoint REA en service », avec un carillon. Les alarmes ont trois niveaux : <b>rouge</b> (grave, klaxon continu), <b>ambre</b> (écart, ronfleur), <b>bleu</b> (information). Une alarme nouvelle <b>clignote</b> jusqu'à son acquittement.</p><p><b>À faire :</b> lisez l'alarme, puis cliquez sur <kbd>Acquitter</kbd> dans le bloc Alarmes. <kbd>Tableau ›</kbd> ouvre le tableau complet, avec toutes les alarmes possibles.</p><p>Acquitter veut dire « j'ai vu », pas « c'est réglé » : l'alarme reste affichée tant que sa cause est présente.</p>",
  ok:s=>Object.values(s.alarms).some(a=>a.on)&&Object.values(s.alarms).every(a=>!a.on||a.ack)},
 {t:'Les automatismes travaillent pour vous',h:"<p>Le bloc <b>Automatismes</b> dit ce que les régulations font en ce moment. Le bore ajouté retire de la réactivité : la puissance tend à baisser, Tmoy passe sous Tref, et la régulation <b>extrait le groupe R</b> pour compenser. Regardez la ligne correspondante, la case Groupe R du bandeau et l'étiquette Groupe R du synoptique.</p><p>Surveiller, c'est aussi vérifier que les automatismes font ce qu'on attend : un automatisme qui ne réagit pas, ou qui réagit trop, est une information aussi importante qu'une alarme.</p><p>Laissez l'appoint se terminer (passez en ×5 si vous voulez), puis <kbd>Suivant</kbd>.</p>",
  ok:s=>!s.rea.run},
 {t:'Comment un opérateur surveille',h:"<p>En salle de commande, la surveillance est un travail actif, pas une attente. Quelques habitudes :</p><ul><li><b>Faire le tour régulièrement.</b> Toutes les quelques minutes, parcourez le bandeau de gauche à droite, puis le synoptique. Pas besoin de tout lire : cherchez <b>ce qui a changé</b>.</li><li><b>Regarder les tendances plus que les valeurs.</b> Une pression de 154 bar stable est normale ; 156 bar qui monte d'un bar par minute ne l'est pas. Les courbes derrière les valeurs servent à ça.</li><li><b>Comparer à la référence.</b> Tmoy à Tref, niveau pressu à son niveau de référence, groupe R dans sa bande de manœuvre : chaque grandeur a une valeur attendue.</li><li><b>Recouper.</b> Avant de croire une mesure surprenante, cherchez une deuxième indication qui la confirme : la pression et le niveau du pressuriseur, le débit d'eau et le débit de vapeur.</li><li><b>Anticiper.</b> Avant une manœuvre, demandez-vous ce qui va bouger et dans quel sens. Si ce n'est pas ce qui se passe, arrêtez-vous.</li></ul>"},
 {t:'Agir avec méthode',h:"<p>Pour chaque action, les exploitants appliquent des pratiques de fiabilité simples :</p><ul><li><b>Une action à la fois</b>, puis on vérifie son effet avant la suivante : je lis, j'agis, je vérifie.</li><li><b>Vérifier qu'on agit sur le bon organe</b> avant de cliquer : la bonne carte, le bon groupe, la bonne valeur.</li><li><b>S'arrêter en cas de doute.</b> Une tranche à l'équilibre peut attendre une minute ; une action mal comprise, non.</li></ul><p>Face à une alarme : <b>acquitter</b> pour faire taire le son, <b>lire</b> l'alarme, <b>confirmer</b> par une autre mesure, <b>chercher la cause</b> avec le synoptique et les courbes, <b>agir</b>, puis <b>vérifier</b> que la situation revient à la normale. Le <b>journal</b> garde la trace de tout, vos actions comme les automatismes.</p><p>Les <b>aléas</b> du menu vous font pratiquer cette méthode, et les <b>corrections commentées</b> la montrent appliquée pas à pas.</p>"},
 {t:'Tutoriel terminé',h:"<p>Vous connaissez le poste : le bandeau pour l'état d'ensemble, le synoptique pour voir et agir vite, les familles de commandes pour tout régler, les vues pour changer d'angle, et le bloc d'attention pour ne rien laisser passer.</p><p>Suite conseillée : le <b>Tutoriel de prise de quart</b>, qui pilote le réacteur avec ce poste.</p>",last:true}
 ]},
{id:'tuto',kind:'tuto',title:'Tutoriel de prise de quart',desc:"Découvrir la salle de commande, la réactivité, les régulations et l'AAR.",diff:1,speed:1,
 init:{P:.5,xe:.5,R:190,G:'cal',coupled:true,modeR:'auto',modeG:'auto'},
 brief:"<p>Durée : 15 à 20 minutes. La tranche est à 50 % de puissance, régulations en automatique. Chaque étape vous demande une action ; le bouton <kbd>Suivant</kbd> s'active quand elle est réalisée.</p>",
 steps:[
 {t:'Bienvenue en salle de commande',h:"<p>Vous êtes l'opérateur réacteur de la tranche 1, un REP 900 MWe à trois boucles (2 785 MWth). Le réacteur fonctionne à <b>50 %</b>, groupes de grappes et régulations en automatique.</p><p>Sur ordinateur, tout tient dans l'écran. Sous le bandeau, au centre : en haut, ce qui demande votre attention (<b>alarmes</b>, <b>mes actions</b> en cours, <b>automatismes</b> en service) ; au milieu, une vue de la tranche ; en bas, les onglets des vues (synoptique, courbes, ΔI, chaussette P-T, réactivité, instrumentation neutronique, tendances, alarmes, journal). À droite : cette consigne, puis les <b>commandes</b>, rangées par famille comme le bandeau (Réactivité, Primaire, Secondaire, Sûreté). Quand une étape parle d'une carte, elle s'ouvre toute seule.</p><p>Sur téléphone, l'écran est rangé en trois zones, <b>Surveiller</b>, <b>Agir</b> et <b>Suivre</b>, que les onglets du bas font passer de l'une à l'autre ; la consigne reste affichée en haut quand vous faites défiler, et chaque carte se replie en touchant son titre. Partout, « Réduire » ramène la consigne à une ligne.</p><p>Le bandeau du haut résume les grandeurs clés et reste toujours visible ; une valeur qui varie s'y affiche en gras avec une flèche. Touchez une case du bandeau pour ouvrir la carte qui la détaille.</p><p>La simulation tourne en temps réel. La vitesse se règle en haut (×1 à ×300) : accélérez pour les phénomènes lents (bore, xénon), revenez à ×1 pour les transitoires rapides.</p>"},
 {t:'Les grandeurs essentielles',h:"<p>Le bandeau du haut est rangé en quatre familles. <b>Cœur</b> : puissance nucléaire, réactivité, groupe R, ΔI, bore. <b>Primaire</b> : Tmoy, températures de branche, pression et niveau du pressuriseur. <b>Secondaire</b> : puissance électrique, pression et niveau des GV. <b>Sûreté</b> : les marges aux protections. Chaque case a son pictogramme. Derrière certaines valeurs, une courbe montre les dernières minutes (plus longtemps en accéléré) ; une ligne d'état indique ce qui est en cours : appoint en bore, rampe de charge, chaufferettes et aspersion, mode des grappes. À côté ou sous la valeur, une ligne de contexte ; en bas, une jauge : vert pour la plage normale, traits rouges pour les seuils. La case ΔI contient le diagramme de pilotage en miniature.</p><p><b>P nucléaire</b> vient des chambres gamme puissance, <b>P électrique</b> de l'alternateur. <b>Tmoy</b> est la température moyenne du primaire ; elle suit un programme linéaire de 286 °C à 0 % à 304,5 °C à 100 %. <b>Tref</b> est calculée à partir de la charge turbine : en mode G, c'est le réacteur qui suit la turbine.</p><p>La <b>pression pressuriseur</b> est régulée à 155 bar par les chaufferettes et l'aspersion. Le <b>niveau GV</b> est tenu vers 50 % par l'eau alimentaire (ARE).</p>"},
 {t:'Le bilan de réactivité',h:"<p>Regardez la carte « Bilan de réactivité » (vue Réactivité sur ordinateur, zone <b>Surveiller</b> sur téléphone) ; le total ρ et le temps de doublement sont aussi dans le bandeau, case « Réactivité ». La réserve du cœur (combustible neuf) est compensée par les <b>grappes</b>, le <b>bore</b> dissous (environ −9 pcm/ppm), l'effet <b>modérateur</b> (coefficient α, d'autant plus négatif que le bore est bas), l'effet <b>Doppler</b> du combustible et l'empoisonnement <b>xénon</b>.</p><p>Quand la somme vaut 0 pcm, le réacteur est critique. Un ρ positif fait apparaître un <b>temps de doublement</b> : avec β = 600 pcm, +100 pcm donnent une période d'environ une minute, soit un temps de doublement d'environ 45 s.</p>"},
 {t:'Passez le groupe R en manuel',h:"<p>Dans <b>Commandes › Grappes</b>, réglez <kbd>Mode R</kbd> sur <kbd>Manuel</kbd>. Le groupe R (régulation de température) ne bougera plus seul.</p>",ok:s=>s.modeR==='man'},
 {t:'Extrayez R de 6 pas',h:"<p>Sélectionnez la carte <b>Groupe R</b> puis appuyez six fois sur <kbd>+1</kbd>.</p><p>Observez : ρ devient positif, la puissance monte, Tmoy monte. Le Doppler et l'effet modérateur, tous deux négatifs, ramènent ρ à zéro et la puissance se stabilise un peu plus haut. C'est l'<b>autorégulation</b> du REP. Attendez une quarantaine de secondes.</p>",
  enter:(s,c,k)=>{k.r0=s.rods.R.p;k.tm=null;},ok:(s,c,k)=>{ if(s.rods.R.p>=k.r0+5.5){ if(k.tm==null)k.tm=s.t; return s.t-k.tm>40; } return false; }},
 {t:'Repassez R en automatique',h:"<p>Réglez <kbd>Mode R</kbd> sur <kbd>Auto</kbd>. La turbine n'a pas changé : Tmoy est au-dessus de Tref, donc la régulation <b>réinsère</b> R jusqu'à recaler Tmoy sur Tref (bande morte ±0,8 °C).</p>",ok:s=>s.modeR==='auto'&&Math.abs(s.Tavg-s.Tref)<0.8},
 {t:'Montez la charge à 60 %',h:"<p>Dans <b>Commandes › Turbine</b>, choisissez la vitesse <kbd>3</kbd> %/min puis amenez la consigne à <b>60 %</b> (curseur ou <kbd>+5 %</kbd> deux fois). Passez en ×5 si vous le souhaitez.</p><p>La charge turbine augmente, Tref aussi. Les <b>GCP</b> s'extraient selon leur courbe de calibrage (ils compensent le défaut de puissance), et R affine la température.</p>",ok:s=>s.Lt>=0.595},
 {t:'Diluez 300 litres',h:"<p>Dans <b>Commandes › Bore</b> : mode <kbd>Dilution</kbd>, débit <kbd>10</kbd> m³/h, volume <kbd>300 L</kbd>, puis <kbd>Lancer l'appoint</kbd>.</p><p>La baisse de bore ajoute de la réactivité ; en automatique, R s'insère pour compenser. On utilise le bore pour garder R dans sa bande de manœuvre (150–215 pas) face aux variations lentes : xénon, usure du combustible.</p>",
  enter:(s,c,k)=>{k.v0=s.volDil;},ok:(s,c,k)=>s.volDil-k.v0>=0.29},
 {t:'Le pressuriseur : aspersion manuelle',h:"<p>Dans <b>Commandes › Pressuriseur</b>, passez l'aspersion en <kbd>Manuel</kbd> et ouvrez le curseur vers 60 %. L'eau froide pulvérisée condense la vapeur : la pression baisse. Les chaufferettes de secours démarrent sous 153,3 bar. Attendez que la pression passe sous 154 bar.</p>",ok:s=>s.sprayMode==='man'&&s.Ppzr<154},
 {t:"Remettez l'aspersion en automatique",h:"<p>Repassez l'aspersion en <kbd>Auto</kbd>. Les chaufferettes ramènent la pression vers 155 bar (environ 2 bar par minute à pleine puissance de chauffe).</p>",ok:s=>s.sprayMode==='auto'&&s.Ppzr>154.5},
 {t:'Les alarmes',h:"<p>Ouvrez <b>Alarmes</b>. Les voyants clignotent tant qu'ils ne sont pas acquittés : rouge pour les alarmes graves, ambre pour les écarts, bleu pour les informations. Comme sur un tableau d'alarmes réel, un avertisseur sonore accompagne l'apparition : <b>klaxon</b> continu pour une alarme rouge, <b>ronfleur</b> pour une ambre, simple carillon pour une information. Il se tait à l'acquittement. Appuyez sur <kbd>Acquitter</kbd>. Le journal de quart enregistre vos actions et les automatismes.</p>",ok:s=>Object.values(s.alarms).every(a=>!a.on||a.ack)},
 {t:"L'arrêt automatique du réacteur",h:"<p>Dans <b>Commandes › Protection</b>, appuyez sur <kbd>AAR manuel</kbd> puis confirmez. Toutes les grappes chutent en moins de 2 secondes, soit plus de 7 000 pcm d'antiréactivité.</p>",ok:s=>s.tripped},
 {t:"Après l'AAR",h:"<p>Observez la suite : la puissance chute brutalement (saut prompt) puis décroît avec une période d'environ −80 s ; il reste la <b>puissance résiduelle</b> (≈ 6 % juste après, quelques % ensuite). La turbine est déclenchée, le GCT-c passe en mode pression et tient 70 bar dans les GV, donc Tmoy redescend vers 286 °C. La contraction du primaire fait baisser niveau et pression pressu, compensés par la charge RCV et les chaufferettes. L'ASG démarre.</p><p>Attendez que Tmoy passe sous 290 °C.</p>",ok:s=>s.Tavg<290},
 {t:'Tutoriel terminé',h:"<p>Vous avez vu l'essentiel : bilan de réactivité, autorégulation, mode G, bore, pressuriseur, alarmes et AAR. Continuez avec les <b>exercices</b> (divergence, montée en charge, suivi de charge, mise à l'arrêt), puis les <b>aléas</b>.</p>",last:true}
 ]},
{id:'l-cin',kind:'lecon',title:'Cinétique et temps de doublement',desc:'Neutrons retardés, saut prompt, période et premier Doppler.',diff:1,speed:2,
 init:{P:.005,critR:140,R:140,G:'cal',coupled:false,xe:0,modeR:'man',modeG:'man'},
 brief:"<p>Réacteur critique à 0,5 % PN, turbine découplée, groupes en manuel. Vous allez provoquer de petites variations de réactivité et observer comment la population neutronique répond.</p>",
 info:s=>'ρ '+sgn(s.rho.tot,0)+' pcm · Td '+(Number.isFinite(s.Td)&&s.Td<99999?fmt(s.Td,0)+' s':(s.rate<-1e-4?'décroissance':'∞'))+' · P '+fmt(s.n*100,3)+' %',
 steps:[
 {t:'Pourquoi un réacteur est pilotable',tab:'synop',h:"<p><b>Le problème.</b> Une génération de neutrons (naissance, ralentissement, nouvelle fission) dure environ 20 microsecondes, soit 50 000 générations par seconde. Avec +100 pcm, chaque génération compte 0,1 % de neutrons de plus que la précédente. Si tous les neutrons naissaient immédiatement, la puissance serait multipliée par 10 en moins d'un dixième de seconde : aucune grappe ne bouge aussi vite.</p><p><b>Ce qui nous sauve.</b> Environ 0,6 % des neutrons, la fraction <b>β</b> (600 pcm), ne naissent pas tout de suite : certains produits de fission les émettent entre quelques dixièmes de seconde et une minute plus tard, une douzaine de secondes en moyenne. Tant que la réactivité reste petite devant β, la réaction en chaîne doit attendre ces retardataires pour s'amplifier : c'est leur délai, et non les 20 µs, qui fixe le rythme.</p><p><b>Le résultat.</b> Avec +100 pcm, la puissance double en 40 à 45 secondes au lieu de quelques millisecondes : l'opérateur et les automatismes ont le temps d'agir. Repère de calcul : la <b>période</b> vaut environ (β − ρ) / (0,08 × ρ) secondes, et le <b>temps de doublement</b> 0,69 fois la période.</p><p><b>La limite.</b> Si la réactivité atteignait β, les neutrons immédiats suffiraient à eux seuls : le réacteur serait <b>prompt-critique</b> et ce délai protecteur disparaîtrait. En conduite, on reste à quelques dizaines de pcm.</p>"},
 {t:'Extrayez R de 5 pas',tab:'cmd',h:"<p>Sélectionnez <b>Groupe R</b> et appuyez cinq fois sur <kbd>+1</kbd>, soit environ +40 pcm à cette cote.</p><p>Observez le bandeau. La puissance fait d'abord un petit <b>saut prompt</b> (≈ ρ / (β − ρ), soit +7 %), puis croît exponentiellement avec un temps de doublement voisin de 2 minutes. Attendez 30 s après la fin du mouvement.</p>",
  enter:(s,c,k)=>{k.r0=s.rods.R.p;},ok:(s,c,k)=>{ if(s.rods.R.p>=k.r0+4.5){ if(k.tm==null)k.tm=s.t; return s.t-k.tm>30; } return false; }},
 {t:"Laissez monter jusqu'à 2 %",h:"<p>Passez en ×5. Au-dessus de 1 % environ, le combustible commence à chauffer et l'effet <b>Doppler</b> (élargissement des résonances d'absorption de l'U-238) retire de la réactivité. ρ diminue tout seul, le temps de doublement s'allonge.</p><p>C'est le <b>point d'échauffement nucléaire</b> : en dessous, la puissance n'a aucune contre-réaction ; au-dessus, elle se stabilise d'elle-même.</p>",ok:s=>s.n>0.02},
 {t:'Insérez R de 10 pas',tab:'cmd',h:"<p>Appuyez sur <kbd>−10</kbd>. ρ passe à environ −60 pcm. La puissance chute d'un coup (saut prompt négatif) puis décroît plus lentement.</p><p>Même pour une forte antiréactivité, la décroissance ne peut pas être plus rapide qu'une période d'environ <b>−80 s</b>, fixée par le groupe de précurseurs le plus long (55 s de demi-vie). C'est pourquoi la puissance neutronique met plusieurs minutes à disparaître après un AAR.</p>",
  enter:(s,c,k)=>{k.r0=s.rods.R.p;},ok:(s,c,k)=>{ if(s.rods.R.p<=k.r0-9){ if(k.tm==null)k.tm=s.t; return s.t-k.tm>40; } return false; }},
 {t:'Revenez à la criticité',h:"<p>Extrayez R de quelques pas (<kbd>+1</kbd> à la fois) jusqu'à ce que la puissance ne bouge plus : temps de doublement infini, ρ ≈ 0. Tenez 30 secondes.</p><p>Vous remarquerez que la cote critique n'est plus tout à fait la même qu'au départ : le combustible est à une autre température.</p>",
  ok:(s,c,k)=>{ if(Math.abs(s.rate)<Math.LN2/600&&s.n>1e-4) k.st=(k.st||0)+DT; else k.st=0; return k.st>30; }},
 {t:'Leçon terminée',h:"<p>Retenez trois ordres de grandeur : <b>β = 600 pcm</b>, <b>+100 pcm ≈ 1 minute de période</b>, <b>−80 s de période limite</b> à la baisse. L'exercice <b>Divergence</b> applique tout cela depuis l'état sous-critique.</p>",last:true}
 ]},
{id:'l-fb',kind:'lecon',title:'Contre-réactions et mode G',desc:'Doppler, coefficient modérateur, défaut de puissance et rôle des GCP.',diff:1,speed:2,
 init:{P:.5,xe:.5,R:190,G:'cal',coupled:true,modeR:'auto',modeG:'auto'},
 brief:"<p>Tranche à 50 %, régulations en automatique. Vous allez couper les automatismes de grappes et observer le réacteur suivre seul la turbine, puis comprendre pourquoi on a besoin des GCP.</p>",
 info:s=>'P '+fmt(s.n*100,1)+' % · charge '+fmt(s.Lt*100,1)+' % · Tmoy − Tref '+sgn(s.Tavg-s.Tref,1)+' °C · Doppler '+fmt(s.rho.dop,0)+' · modérateur '+fmt(s.rho.mod,0),
 steps:[
 {t:'Deux contre-réactions négatives',tab:'synop',h:"<p><b>Doppler</b> : quand le combustible chauffe, l'U-238 absorbe davantage. Environ −1,8 pcm/°C de combustible, soit près de −1 000 pcm entre 0 et 100 %.</p><p><b>Modérateur</b> : quand l'eau chauffe, elle se dilate et ralentit moins bien les neutrons. Le coefficient α dépend du bore : vers −5 pcm/°C à 1 300 ppm, vers −45 pcm/°C en fin de cycle. Il est affiché dans le bilan de réactivité.</p><p>La somme des deux entre 0 et 100 % est le <b>défaut de puissance</b>, environ −1 400 pcm ici. Il faut le compenser pour monter en puissance.</p>"},
 {t:'Passez R et GCP en manuel',tab:'cmd',h:"<p>Réglez <kbd>Mode R</kbd> et <kbd>Mode GCP</kbd> sur <kbd>Manuel</kbd>. Plus aucune grappe ne bougera.</p>",ok:s=>s.modeR==='man'&&s.modeG==='man'},
 {t:'Montez la charge à 60 % sans toucher aux grappes',tab:'cmd',h:"<p>Vitesse <kbd>5</kbd> %/min, consigne <b>60 %</b>. Regardez la ligne d'information.</p><p>La turbine prélève plus de vapeur, le primaire se refroidit. Avec α négatif, ce refroidissement ajoute de la réactivité : la puissance nucléaire <b>suit la turbine sans aucune action</b>. Mais il faut environ 6 °C de refroidissement pour fournir les ~140 pcm du défaut de puissance, alors que Tref, elle, monte. L'écart Tmoy − Tref se creuse vers −6 °C. Attendez une minute à 60 %.</p>",
  ok:(s,c,k)=>{ if(s.Lt>=0.595){ if(k.tm==null)k.tm=s.t; return s.t-k.tm>60; } return false; }},
 {t:'Rendez la main aux GCP',tab:'cmd',h:"<p>Passez <kbd>Mode GCP</kbd> en <kbd>Auto</kbd>. Les GCP rejoignent leur <b>courbe de calibrage</b> : une position fixée par la charge turbine, calculée pour compenser le défaut de puissance. Ils s'extraient d'une dizaine de pas et Tmoy remonte vers Tref.</p><p>C'est le principe du <b>mode G</b> : les GCP compensent en boucle ouverte, R affine en boucle fermée.</p>",ok:s=>s.modeG==='auto'&&Math.abs(s.rods.G.p-calG(s.Lt))<1},
 {t:'Rendez la main à R',tab:'cmd',h:"<p>Passez <kbd>Mode R</kbd> en <kbd>Auto</kbd>. R corrige l'écart résiduel jusqu'à Tmoy = Tref à ±0,8 °C près.</p>",ok:s=>s.modeR==='auto'&&Math.abs(s.Tavg-s.Tref)<0.8},
 {t:'Leçon terminée',h:"<p>Le REP est naturellement stable grâce à ses coefficients négatifs ; les grappes servent surtout à tenir la <b>température</b> sur son programme, pas à « fournir » la puissance. Un α moins négatif (bore élevé, début de cycle) rend la tranche plus molle ; très négatif (fin de cycle), elle réagit fortement à tout refroidissement.</p>",last:true}
 ]},
{id:'l-di',kind:'lecon',title:'Le ΔI et le diagramme de pilotage',desc:'Distribution axiale de puissance : effet des grappes, du bore et du xénon.',diff:2,speed:5,
 init:{P:.5,xe:.5,R:190,G:'cal',coupled:true,modeR:'auto',modeG:'auto'},
 brief:"<p>Tranche à 50 %. Vous allez déformer la distribution axiale de puissance avec le groupe R, puis la corriger. Gardez le <b>diagramme ΔI</b> visible (vue ΔI, ou zone Surveiller sur téléphone) ; l'écart à la référence est aussi dans le bandeau, case « ΔI » et passez en ×10 pendant les appoints.</p>",
 info:s=>'ΔI '+fmt(s.DI,2)+' % PN · réf. '+fmt(-1.5*s.n,2)+' · écart '+sgn(s.DI+1.5*s.n,2)+' · R '+fmt(s.rods.R.p,0)+' · Tmoy − Tref '+sgn(s.Tavg-s.Tref,1)+' °C',
 steps:[
 {t:"Qu'est-ce que le ΔI ?",tab:'synop',h:"<p>Les chambres gamme puissance ont deux sections, haute et basse. <b>ΔI = P(haut) − P(bas)</b>, en % de la puissance nominale. Rapporté à la puissance, c'est l'<b>axial offset</b> : AO = ΔI / P.</p><p>Pourquoi le surveiller : un flux trop concentré en haut ou en bas crée des points chauds (facteur de forme), qui réduisent les marges à la crise d'ébullition et en cas d'accident de perte de réfrigérant. Il favorise aussi les <b>oscillations xénon axiales</b>.</p><p>En exploitation on garde ΔI dans un domaine autour d'un <b>ΔI de référence</b> (ici −1,5 % × P) ± 5 % PN : la bande verte du diagramme, inclinée parce que la référence suit la puissance. Sur les tranches réelles, le domaine s'élargit souvent à basse puissance. Une marge ΔI dégradée réduit aussi le seuil de protection ΔT surtempérature.</p>"},
 {t:'Insérez R de 40 pas',tab:'cmd',h:"<p>Passez <kbd>Mode R</kbd> en <kbd>Manuel</kbd>, puis <kbd>−10</kbd> quatre fois (190 → 150 pas).</p><p>Les grappes entrent par le <b>haut</b> du cœur : elles y écrasent le flux. Sur le diagramme, le point part vers la gauche (ΔI plus négatif). La puissance baisse un moment puis revient, car la turbine tire toujours 50 % : c'est Tmoy qui chute de plusieurs degrés.</p>",
  enter:(s,c,k)=>{k.r0=s.rods.R.p;},ok:(s,c,k)=>s.modeR==='man'&&s.rods.R.p<=k.r0-39.5},
 {t:'Compensez au bore',tab:'cmd',h:"<p>Dans <b>Bore</b> : <kbd>Dilution</kbd>, <kbd>30</kbd> m³/h, <kbd>Continu</kbd>, puis <kbd>Lancer l'appoint</kbd>. Passez en ×10. Arrêtez l'appoint quand Tmoy − Tref est revenu à moins de 0,5 °C (il faut environ 7 m³).</p><p>Résultat : même puissance, même Tmoy… mais le ΔI reste décalé. Le bore est réparti uniformément dans le cœur, il ne déforme pas le flux ; les grappes, si.</p>",
  enter:(s,c,k)=>{k.v0=s.volDil;},ok:(s,c,k)=>!s.rea.run&&s.volDil-k.v0>1&&Math.abs(s.Tavg-s.Tref)<0.6},
 {t:'Ramenez R dans sa bande par borication',tab:'cmd',h:"<p>Passez <kbd>Mode R</kbd> en <kbd>Auto</kbd> : il ne bouge pas, car la température est déjà juste. <b>La position de R est imposée par le bore.</b></p><p>Lancez une <kbd>Borication</kbd> à <kbd>10</kbd> m³/h en <kbd>Continu</kbd>. Tmoy baisse, R s'extrait pour compenser. Arrêtez l'appoint quand R dépasse 185 pas (environ 0,9 m³). Le point du diagramme revient vers la référence.</p>",
  enter:(s,c,k)=>{k.r0=s.rods.R.p;},ok:(s,c,k)=>s.modeR==='auto'&&s.rods.R.p>=185&&!s.rea.run},
 {t:'Et le xénon ?',h:"<p>Le xénon se forme là où le flux était plusieurs heures auparavant. Si le flux bascule vers le bas, le haut du cœur se « désempoisonne » pendant que le bas s'empoisonne, puis la situation s'inverse : c'est l'<b>oscillation axiale xénon</b>, de période ~24 h, qui peut diverger dans un grand cœur. Les opérateurs l'amortissent en jouant sur R au bon moment.</p><p>Le simulateur n'en modélise qu'un effet simplifié : une lente dérive du ΔI qui suit les mouvements de grappes avec quelques heures de retard. C'est pour cela qu'on <b>compense le xénon au bore</b> et non aux grappes.</p>"},
 {t:'Leçon terminée',h:"<p>Règle d'exploitation : les grappes pour les transitoires rapides et la température, le bore pour les variations lentes de réactivité, le ΔI comme juge de paix. L'exercice <b>Suivi de charge et xénon</b> met tout cela en pratique.</p>",last:true}
 ]},
{id:'l-xe',kind:'lecon',title:'Le xénon 135',desc:'Empoisonnement, pic après baisse de charge et après arrêt.',diff:2,speed:60,
 init:P100,
 brief:"<p>Pleine puissance, xénon à l'équilibre. Leçon longue en temps simulé (plusieurs heures) : utilisez ×300. Ouvrez <b>Tendances</b>, activez la courbe <b>Xénon</b> et la fenêtre <b>8 h</b>.</p>",
 info:(s,c)=>'ρ Xe '+fmt(s.rho.xe,0)+' pcm · Tmoy − Tref '+sgn(s.Tavg-s.Tref,1)+' °C · R '+fmt(s.rods.R.p,0)+' pas · bore '+fmt(s.Cb,0)+' ppm',
 steps:[
 {t:'Un poison qui se fabrique et se brûle',tab:'trend',h:"<p>L'iode 135 (demi-vie 6,6 h) est un produit de fission abondant ; il décroît en <b>xénon 135</b> (9,2 h), l'absorbant neutronique le plus puissant connu. Le xénon disparaît de deux façons : par décroissance, et surtout par <b>capture neutronique</b> (« brûlage ») tant que le flux est élevé.</p><p>À pleine puissance l'équilibre coûte environ <b>−2 700 pcm</b>. Si le flux baisse, le brûlage diminue tout de suite alors que l'iode accumulé continue d'alimenter le xénon : celui-ci <b>monte</b> pendant plusieurs heures.</p>"},
 {t:'Baissez la charge à 50 %',tab:'cmd',h:"<p>Vitesse <kbd>10</kbd> %/min, consigne <b>50 %</b>, groupes en automatique.</p>",ok:s=>s.Lt<=0.505},
 {t:'Observez 4 heures',tab:'trend',h:"<p>Passez en ×300 et regardez la courbe Xénon. ρ Xe devient plus négatif pendant plusieurs heures. R s'extrait pour compenser jusqu'à sa butée haute, puis Tmoy décroche sous Tref.</p><p>Gardez Tmoy sur Tref par de petites <b>dilutions</b> (10 m³/h, 300 L à 1 m³). La leçon avance après 4 h simulées.</p>",
  enter:(s,c,k)=>{k.t0=s.t;},ok:(s,c,k)=>s.t-k.t0>=4*3600,info:(s,c,k)=>'Écoulé '+dur(s.t-(k.t0||s.t))+' / 4 h · ρ Xe '+fmt(s.rho.xe,0)+' pcm · Tmoy − Tref '+sgn(s.Tavg-s.Tref,1)+' °C'},
 {t:'Remontez à 100 %',tab:'cmd',h:"<p>Consigne <b>100 %</b> à 5 %/min. Le flux augmente, le xénon est brûlé plus vite qu'il ne se forme : il libère de la réactivité. R s'insère ; si ça ne suffit pas, il faut <b>borer</b>. Gardez un œil sur ΔI.</p>",ok:s=>s.Lt>=0.995},
 {t:'Le pic xénon après arrêt (facultatif)',tab:'cmd',h:"<p>Faites un <b>AAR manuel</b> et laissez tourner 10 h en ×300. Sans flux, plus de brûlage : le xénon culmine vers 8 à 11 h après l'arrêt, environ 2 000 à 2 500 pcm au-delà de l'équilibre, puis décroît en deux jours.</p><p>Pendant ce pic, redémarrer peut être impossible, faute de réactivité disponible : c'est l'empoisonnement post-arrêt. Utilisez <kbd>Suivant</kbd> pour passer cette étape.</p>",
  enter:(s,c,k)=>{k.pk=0;},ok:s=>s.tripped&&s.t-s.tripT>=10*3600,info:(s,c,k)=>{ k.pk=Math.min(k.pk||0,s.rho.xe); return 'ρ Xe '+fmt(s.rho.xe,0)+' pcm · minimum atteint '+fmt(k.pk,0)+' pcm'+(s.tripped?' · '+dur(s.t-s.tripT)+' après AAR':''); },opt:true},
 {t:'Leçon terminée',h:"<p>Le xénon impose le rythme des variations de charge : toute baisse se paie par une dilution quelques heures plus tard, toute remontée par une borication. Anticiper vaut mieux que corriger.</p>",last:true}
 ]},
{id:'l-pzr',kind:'lecon',title:'Le pressuriseur et le RCV',desc:'Pression, niveau programmé, chaufferettes, aspersion et charge.',diff:1,speed:2,
 init:P100,
 brief:"<p>Pleine puissance. Vous allez provoquer des variations de volume du primaire et observer comment pression et niveau sont tenus.</p>",
 info:s=>'P '+fmt(s.Ppzr,2)+' bar · niveau '+fmt(s.Lpzr,1)+' / réf. '+fmt(s.Lref,1)+' % · chauffage '+fmt(s.hEff*1440,0)+' kW · aspersion '+fmt(s.spray*100,0)+' % · charge '+fmt(s.Qc,1)+' m³/h',
 steps:[
 {t:'Une bulle de vapeur qui fixe la pression',tab:'synop',h:"<p>Le pressuriseur contient de l'eau et de la vapeur <b>à saturation</b> : 155 bar correspondent à 345 °C. La pression du primaire est donc fixée par la température de cette eau.</p><p>Pour monter la pression on chauffe (<b>chaufferettes</b>, 1 440 kW dont 216 kW proportionnelles). Pour la baisser on pulvérise de l'eau froide de branche froide dans la vapeur (<b>aspersion</b>). Au-delà de 166,6 bar, les soupapes <b>SEBIM</b> s'ouvrent.</p><p>Le pressuriseur est aussi le vase d'expansion : son <b>niveau programmé</b> suit Tmoy (≈ 20 % à 286 °C, 61 % à 304,5 °C), tenu par le <b>RCV</b> qui charge et décharge en permanence (13,6 m³/h).</p>"},
 {t:'Baissez la charge à 80 %',tab:'cmd',h:"<p>Vitesse <kbd>10</kbd> %/min, consigne <b>80 %</b>. Tmoy baisse : l'eau se contracte, le pressuriseur se vide (<b>outsurge</b>), la vapeur se détend et la pression baisse. Les chaufferettes de secours démarrent et la charge RCV augmente pour suivre le niveau programmé.</p>",
  ok:(s,c,k)=>{ if(s.Lt<=0.805){ if(k.tm==null)k.tm=s.t; return s.t-k.tm>30; } return false; }},
 {t:'Chaufferettes en marche forcée',tab:'cmd',h:"<p>Réglez <b>Chaufferettes</b> sur <kbd>Forcé</kbd>. La pression monte d'environ 1,5 bar/min jusqu'à ce que l'aspersion automatique s'ouvre et l'équilibre vers 156 bar.</p>",ok:s=>s.heatMode==='on'&&s.Ppzr>155.6},
 {t:'Repassez les chaufferettes en auto',tab:'cmd',h:"<p>Réglez <b>Chaufferettes</b> sur <kbd>Auto</kbd>. L'aspersion ramène la pression à 155 bar.</p>",ok:s=>s.heatMode==='auto'},
 {t:'Charge RCV en manuel',tab:'cmd',h:"<p>Passez la <b>Charge</b> en <kbd>Manuel</kbd> et réglez le curseur vers 5 m³/h. Charge &lt; décharge : le primaire perd de l'eau, le niveau baisse lentement sous sa référence (passez en ×5). Attendez un écart de 2,5 %.</p><p>Sous 14 %, la décharge s'isole et les chaufferettes se coupent pour ne pas brûler à sec.</p>",ok:s=>s.chgMode==='man'&&s.Lpzr<s.Lref-2.5},
 {t:'Charge RCV en auto',tab:'cmd',h:"<p>Repassez la <b>Charge</b> en <kbd>Auto</kbd> : le débit monte et le niveau rejoint sa référence.</p>",ok:s=>s.chgMode==='auto'&&Math.abs(s.Lpzr-s.Lref)<2},
 {t:'Leçon terminée',h:"<p>Toute variation de Tmoy se lit d'abord au pressuriseur : environ 2 % de niveau et 0,7 bar par °C. Un niveau qui baisse sans variation de température signe une perte d'inventaire : fuite ou décharge excessive.</p>",last:true}
 ]},
{id:'l-gv',kind:'lecon',title:'Générateurs de vapeur et eau alimentaire',desc:'Pression vapeur, contraction et gonflement, régulation trois éléments, perte d\'eau.',diff:1,speed:2,
 init:P100,
 brief:"<p>Pleine puissance. En huit étapes courtes, vous allez voir le niveau des générateurs de vapeur se <b>contracter</b> puis <b>gonfler</b> quand la charge change, la régulation ARE <b>trois éléments</b> le recaler, et ce qui se passe quand l'eau alimentaire <b>manque</b>.</p><p>Gardez sous les yeux la carte <b>Eau alimentaire — ARE / ASG</b> (onglet Agir) : à chaque étape, la ligne de mesures sous la consigne dit quoi regarder.</p>",
 info:s=>'Niveau GV '+fmt(s.Lsg,1)+' % · vapeur '+fmt(s.Wst*100,0)+' % · ARE '+fmt(s.Wf*100,0)+' % · P GV '+fmt(s.Psg,1)+' bar',
 steps:[
 {t:'Le GV, frontière entre deux circuits',tab:'cmd',h:"<p>L'eau primaire circule dans ~3 300 tubes en U par GV et fait bouillir l'eau secondaire. La pression vapeur est celle de saturation de l'eau du GV : <b>70 bar à 0 %</b> (286 °C) et <b>57,5 bar à 100 %</b>, car il faut un écart de température pour transmettre la chaleur.</p><p><b>À observer</b> dans la carte Eau alimentaire : débit ARE ≈ débit vapeur, niveau stable à 50 %. Tout ce qui sort en vapeur rentre en eau.</p>",
  info:s=>'Bilan eau − vapeur '+sgn((s.Wf-s.Wst)*100,1)+' % · niveau GV '+fmt(s.Lsg,1)+' % · P GV '+fmt(s.Psg,1)+' bar'},
 {t:'Contraction : baisse rapide de charge',tab:'cmd',h:"<p>Le <b>niveau gamme étroite</b> se mesure dans une émulsion eau-vapeur. Si le débit vapeur baisse, la pression monte, les bulles s'écrasent : l'émulsion se tasse et le niveau <b>baisse</b> un instant. C'est la <b>contraction</b>.</p><p>Vitesse <kbd>30</kbd> %/min, consigne <b>70 %</b>. <b>À observer</b> : le niveau descend alors que le débit ARE est <i>supérieur</i> au débit vapeur. La pression vapeur monte vers 61 bar.</p>",
  ok:(s,c,k)=>{ if(s.Lt<=0.705){ if(k.tm==null)k.tm=s.t; return s.t-k.tm>20; } return false; },
  info:(s,c,k)=>'Niveau '+fmt(s.Lsg,1)+' % (le plus bas '+fmt(k.minLg,1)+' %) · ARE − vapeur '+sgn((s.Wf-s.Wst)*100,1)+' % · P GV '+fmt(s.Psg,1)+' bar'},
 {t:'La régulation trois éléments recale le niveau',tab:'cmd',h:"<p>Une régulation qui ne regarderait que le niveau ferait l'inverse de ce qu'il faut : pendant la contraction, elle ajouterait de l'eau, et le niveau déborderait ensuite. La régulation ARE combine donc <b>trois éléments</b> : le <b>débit vapeur</b> (elle envoie d'abord autant d'eau qu'il sort de vapeur), le <b>niveau</b> (petite correction lente vers 50 %) et le <b>débit d'eau</b> mesuré (elle vérifie que la vanne donne bien ce qu'elle demande).</p><p><b>À observer</b> : le débit ARE rejoint le débit vapeur et le niveau revient à 50 %, sans dépassement marqué. Attendez.</p>",
  ok:(s,c,k)=>s.t-k.ts>30&&Math.abs(s.Lsg-50)<0.5&&Math.abs(s.Wf-s.Wst)<0.02,
  info:s=>'Niveau '+fmt(s.Lsg,1)+' % → 50 % · ARE '+fmt(s.Wf*100,1)+' % pour '+fmt(s.Wst*100,1)+' % de vapeur'},
 {t:'Gonflement : remontée rapide de charge',tab:'cmd',h:"<p>Effet inverse : si la turbine demande plus de vapeur, la pression baisse, l'eau se vaporise davantage et l'émulsion <b>gonfle</b>.</p><p>Toujours à <kbd>30</kbd> %/min, consigne <b>90 %</b>. <b>À observer</b> : le niveau <i>monte</i> alors que le GV perd plus de vapeur qu'il ne reçoit d'eau. La pression vapeur redescend.</p>",
  ok:(s,c,k)=>{ if(s.Lt>=0.895){ if(k.tm==null)k.tm=s.t; return s.t-k.tm>20; } return false; },
  info:(s,c,k)=>'Niveau '+fmt(s.Lsg,1)+' % (le plus haut '+fmt(k.maxLg,1)+' %) · ARE − vapeur '+sgn((s.Wf-s.Wst)*100,1)+' % · P GV '+fmt(s.Psg,1)+' bar'},
 {t:"Prenez l'ARE en manuel",tab:'cmd',h:"<p>Passez la <b>Régul. ARE</b> en <kbd>Manuel</kbd> et réglez le débit vers <b>75 %</b>, environ 15 points sous le débit vapeur (≈ 90 %).</p><p><b>À observer</b> : plus rien ne compense la vapeur qui part. Le niveau commence à baisser. Attendez qu'il passe sous 47 %.</p>",
  ok:s=>s.areMode==='man'&&s.Wf<s.Wst-0.08&&s.Lsg<47,
  info:s=>'Niveau '+fmt(s.Lsg,1)+' % · ARE '+fmt(s.Wf*100,0)+' % contre '+fmt(s.Wst*100,0)+' % de vapeur'},
 {t:'Le GV se vide : combien de temps ?',tab:'cmd',h:"<p>Le seuil d'<b>AAR niveau GV très bas</b> est à <b>15 %</b> : en dessous, le GV ne garantit plus le refroidissement du primaire.</p><p><b>À observer</b> : la ligne de mesures calcule le temps qu'il reste avant ce seuil au rythme actuel. Avec un déficit de 15 points, il reste quelques minutes ; avec une perte <b>totale</b> d'eau alimentaire à pleine puissance, moins d'une minute. Attendez que le niveau passe sous 40 %.</p>",
  ok:s=>s.Lsg<40,
  info:(s,c,k)=>{ const now=s.t; if(k.rt==null||now-k.rt>=5){ if(k.rt!=null) k.rate=(s.Lsg-k.rl)/(now-k.rt); k.rt=now; k.rl=s.Lsg; }
   const r=k.rate||0; if(s.Lsg<=15) return 'Niveau '+fmt(s.Lsg,1)+' % · seuil AAR de 15 % atteint';
   return 'Niveau '+fmt(s.Lsg,1)+' % · '+(r<-0.005?'baisse de '+fmt(-r,2)+' %/s · seuil AAR 15 % dans ≈ '+dur((s.Lsg-15)/-r):'pente en cours de mesure')+(s.Wst>0.05?' · sans aucune eau : ≈ '+dur((s.Lsg-15)/(0.8*s.Wst)):''); } },
 {t:"Rendez la main à l'ARE",tab:'cmd',h:"<p>Repassez en <kbd>Auto</kbd>. <b>À observer</b> : la régulation envoie nettement plus d'eau qu'il ne sort de vapeur tant que le niveau est bas, puis réduit l'écart à mesure qu'il remonte vers 50 %.</p>",
  ok:s=>s.areMode==='auto'&&s.Lsg>47,
  info:s=>'Niveau '+fmt(s.Lsg,1)+' % · ARE − vapeur '+sgn((s.Wf-s.Wst)*100,1)+' %'},
 {t:'Leçon terminée',h:"<p>À retenir : un niveau GV se lit avec le débit vapeur. Une baisse de charge le fait d'abord baisser (contraction), une hausse le fait d'abord monter (gonflement) ; c'est pour cela que la régulation ARE suit le débit vapeur avant le niveau.</p><p>Les secours de l'eau alimentaire : <b>APD</b> (motopompe de démarrage), puis <b>ASG</b> (alimentation de secours, démarrée sur AAR ou niveau bas). Côté vapeur : <b>GCT-c</b> vers le condenseur, <b>GCT-a</b> à l'atmosphère, puis soupapes de sûreté vers 85 bar. L'aléa <b>Perte d'une turbopompe alimentaire</b> met ces notions sous pression.</p>",last:true}
 ]},
{id:'l-prot',kind:'lecon',title:'Protections et permissifs',desc:'Seuils d\'AAR, marge ΔT surtempérature, P6, P7, P10.',diff:2,speed:2,
 init:P100,
 brief:"<p>Pleine puissance. Vous allez réduire volontairement une marge de protection, sans aller jusqu'à l'AAR.</p>",
 info:s=>'Marge ΔT '+fmt(s.dtMargin,1)+' % · seuil surtempérature '+fmt(s.OTsp,1)+' % · surpuissance '+fmt(s.OPsp,1)+' % · P '+fmt(s.Ppzr,1)+' bar',
 steps:[
 {t:'La chaîne de protection',tab:'cmd',h:"<p>Le système de protection compare des mesures redondantes à des seuils et déclenche l'<b>AAR</b> (chute de toutes les grappes) ou l'<b>injection de sécurité</b>. Seuils principaux du simulateur :</p><ul><li>haut flux 109 % (25 % tant que le seuil bas n'est pas bloqué, ce qui n'est permis qu'au-dessus de P10), gamme source 10⁵ c/s ;</li><li>pression pressu 165 bar et 131 bar, IS à 119 bar ;</li><li>niveau GV très bas 15 %, perte de pompe primaire au-dessus de P7 ;</li><li><b>ΔT surpuissance</b> et <b>ΔT surtempérature</b>.</li></ul><p>Le ΔT entre branches chaude et froide mesure la puissance thermique. Le seuil de surtempérature baisse quand Tmoy monte, quand la pression baisse ou quand ΔI s'écarte : il protège contre la <b>crise d'ébullition</b>.</p>"},
 {t:'Réduisez la marge ΔT',tab:'cmd',h:"<p>Passez l'<b>aspersion</b> en <kbd>Manuel</kbd> à 40 % (×2 conseillé). La pression baisse. Sous ~149 bar, le seuil de surtempérature devient le plus restrictif et la marge ΔT diminue de 1 % par bar. Suivez-la dans le bandeau, famille Sûreté : sa jauge se rapproche du trait rouge.</p><p>Arrêtez-vous quand la marge passe sous 9 %. L'alarme sonne à 5 %, l'AAR tombe à 0 %.</p>",ok:s=>s.sprayMode==='man'&&s.dtMargin<9},
 {t:"Repassez l'aspersion en auto",tab:'cmd',h:"<p>Repassez l'aspersion en <kbd>Auto</kbd> : les chaufferettes remontent la pression et la marge revient à 12 %.</p>",ok:s=>s.sprayMode==='auto'&&s.Ppzr>153},
 {t:'Les permissifs',h:"<p>Certaines protections n'ont de sens que dans une plage de puissance. Les <b>permissifs</b> les activent ou les inhibent :</p><ul><li><b>P6</b> (GI > 10⁻¹⁰ A) : autorise l'inhibition de la gamme source, qui saturerait au-delà ;</li><li><b>P7</b> (10 %) : active les AAR sur basse pression, niveau pressu haut, perte de pompe primaire, déclenchement turbine ;</li><li><b>P10</b> (10 % GP) : autorise l'opérateur à <b>bloquer</b> le seuil bas de haut flux (25 %), qui protège contre une excursion de puissance au démarrage. Il faut le bloquer pour monter au-delà de 25 % ; sans blocage, un retrait de grappes intempestif est arrêté à 25 %</li></ul><p>En redescendant sous ces seuils, les protections se réarment automatiquement.</p>"},
 {t:'Leçon terminée',h:"<p>Les seuils d'AAR sont calculés pour qu'aucun transitoire ne dépasse les limites de sûreté (crise d'ébullition, fusion à cœur, pression du circuit). Le rôle de l'opérateur est de garder ses marges, pas de « jouer » avec les seuils. Les aléas <b>Aspersion bloquée ouverte</b> et <b>Retrait incontrôlé</b> s'appuient sur cette leçon.</p>",last:true}
 ]},
{id:'l-elec',kind:'lecon',title:"D'où vient le courant de la centrale ?",desc:'Soutirage, auxiliaire, tableaux normaux et secourus, diesels, îlotage.',diff:1,speed:2,
 init:P100,
 brief:"<p>Pleine puissance. En six étapes, vous allez voir qui alimente les pompes et les systèmes de sûreté, démarrer un diesel de secours et vivre un <b>îlotage</b> du point de vue des tableaux électriques.</p><p>Gardez sous les yeux la vue <b>Électrique</b> : elle s'ouvre à chaque étape.</p>",
 info:s=>{ const e=s.el; return 'LG '+(e.src.LG||'hors tension')+' · LHA '+(e.src.LHA||'hors tension')+' · LHB '+(e.src.LHB||'hors tension')+' · diesel A '+({pret:'prêt',demarrage:'démarrage',service:'en service',defaut:'défaut'})[e.dg.A.st]; },
 steps:[
  {t:'La centrale consomme sa propre électricité',tab:'synop',h:"<p>Les trois pompes primaires font chacune environ 6 MW, les pompes alimentaires et le condenseur autant : une tranche de 900 MWe consomme quelques % de ce qu'elle produit. En marche, elle se sert elle-même : une partie du courant de l'alternateur repart vers la tranche par le <b>transformateur de soutirage (TS)</b>.</p><p>Ce courant arrive sur des <b>tableaux 6,6 kV</b> :</p><ul><li>les tableaux <b>normaux</b> LGA à LGD : pompes primaires, pompes alimentaires, condenseur ;</li><li>deux tableaux <b>secourus</b>, LHA (voie A) et LHB (voie B) : les systèmes de sûreté, IS, charge RCV, motopompes ASG, une partie des chaufferettes.</li></ul><p><b>À observer</b> dans la vue Électrique : les trois tableaux « sur TS », le TA « en attente », les diesels « prêts ».</p>"},
  {t:'Démarrez le diesel A',tab:'synop',h:"<p>Chaque voie secourue a son <b>diesel de secours</b>, un moteur de plusieurs MW qui démarre seul en une dizaine de secondes si son tableau perd la tension. Pour vérifier qu'il en est capable, on l'essaie régulièrement.</p><p>Sous le schéma, appuyez sur <kbd>Démarrer diesel A</kbd>. <b>À observer</b> : le compte à rebours, puis « en service », 6,6 kV et 50 Hz. Le diesel tourne mais ne reprend pas LHA : le TS l'alimente toujours, et il n'y a aucune raison de changer de source.</p>",ok:s=>s.el.dg.A.st==='service'},
  {t:'Arrêtez le diesel A',tab:'synop',h:"<p>Le diesel a montré qu'il démarre et tient sa tension. Appuyez sur <kbd>Arrêter diesel A</kbd> : il revient « prêt », c'est-à-dire en attente d'un manque de tension.</p><p><b>À observer</b> : un diesel qui alimente son tableau ne peut pas être arrêté par ce bouton. Le simulateur refuse, comme le ferait la logique d'une vraie tranche.</p>",ok:s=>s.el.dg.A.st==='pret'},
  {t:'Le réseau 400 kV disparaît : îlotage',tab:'synop',enter:s=>{ s.grid=false; if(s.coupled) s.ilot=true; logEv(s,'auto','Perte du réseau 400 kV (leçon)'); },h:"<p>Le réseau 400 kV vient de disparaître. Le disjoncteur de ligne s'ouvre, la turbine perd presque toute sa charge et se cale sur les besoins de la tranche : c'est l'<b>îlotage</b>. Le GCT-c envoie la vapeur en trop au condenseur, les grappes s'enfoncent.</p><p><b>À observer</b> dans la vue Électrique : l'alternateur « îloté · auxiliaires », et les trois tableaux toujours « sur TS ». Personne n'a rien remarqué côté pompes : c'est tout l'intérêt de l'îlotage. Attendez une minute.</p>",ok:(s,c,k)=>s.t-k.ts>60},
  {t:'Le réseau revient : recouplez',tab:'synop',enter:s=>{ s.grid=true; logEv(s,'auto','Réseau 400 kV de nouveau disponible'); },h:"<p>Le réseau est revenu. Dans la carte Turbine (Agir › Secondaire), appuyez sur <kbd>Recoupler</kbd>. La charge reste d'abord à son niveau d'îlotage ; vous pourrez la remonter ensuite.</p><p><b>À retenir</b> : si l'îlotage avait échoué, la turbine aurait déclenché, le TS n'aurait plus rien reçu et les tableaux seraient passés sur le <b>TA</b>, alimenté par le réseau 225 kV. Si le 225 kV manquait aussi, les diesels auraient repris LHA et LHB, et les pompes primaires se seraient arrêtées.</p>",ok:s=>s.coupled&&!s.ilot},
  {t:'Leçon terminée',h:"<p>La chaîne des secours, dans l'ordre : <b>TS</b> (l'alternateur lui-même), <b>TA</b> (réseau 225 kV), les deux <b>diesels</b>, puis les moyens ultimes : <b>DUS</b>, turboalternateur <b>LLS</b>, et sans aucun courant la <b>turbopompe ASG</b>, entraînée par la vapeur, avec les <b>batteries</b> pour le contrôle-commande. Les aléas <b>Perte des alimentations externes</b>, <b>Un diesel refuse de démarrer</b> et <b>Perte du tableau LHB</b>, et l'exercice <b>Perte totale des sources électriques</b>, s'appuient sur cette leçon. La visite « Découvrir la centrale » va plus loin, jusqu'à Fukushima.</p>",last:true}
 ]},
{id:'l-div',kind:'lecon',title:'Divergence guidée',desc:'Approche sous-critique pas à pas, avec 1/M et extrapolation.',diff:2,speed:5,
 init:{P:0,critR:170,R:0,G:'cal',SD:225,coupled:false,xe:0,modeR:'man',modeG:'man'},
 brief:"<p>Version guidée de l'exercice Divergence. Arrêt à chaud, groupes d'arrêt extraits, R inséré, position critique estimée <b>170 pas ± 25</b>. Passez en ×10 pendant les attentes.</p>",
 info:(s,c)=>{ if(c.k.c0==null) c.k.c0=s.n; const cps=s.n*1e10; return 'R '+fmt(s.rods.R.p,0)+' pas · GS '+(s.srInhib?'inhibée':fmt(cps,0)+' c/s')+' · 1/M '+fmt(c.k.c0/s.n,3)+' · ρ '+sgn(s.rho.tot,0)+' pcm · Td '+(Number.isFinite(s.Td)&&s.Td<99999?fmt(s.Td,0)+' s':'∞'); },
 steps:[
 {t:'La multiplication sous-critique',h:"<p>Même sous-critique, le cœur contient une <b>source</b> de neutrons (sources primaire et secondaire, fissions spontanées). Chaque neutron source engendre une chaîne qui s'éteint, d'autant plus longue que k est proche de 1. Le comptage vaut N = S / (1 − k).</p><p>La <b>multiplication</b> M = N / N₀ tend vers l'infini à la criticité. Son inverse <b>1/M</b> tend vers 0 : en le traçant en fonction de la position des grappes et en prolongeant la droite, on <b>prédit la cote critique</b> avant de l'atteindre.</p>"},
 {t:'R à 100 pas',tab:'cmd',h:"<p>Sélectionnez <b>Groupe R</b>, amenez-le à 100 pas (<kbd>+10</kbd> × 10) puis attendez que le comptage se stabilise (Td infini). Notez 1/M : environ 0,57.</p>",ok:(s,c,k)=>{ if(s.rods.R.p>=99.5&&Math.abs(s.rate)<0.0015) k.st=(k.st||0)+DT; else k.st=0; return k.st>20; }},
 {t:'R à 140 pas',tab:'cmd',h:"<p>Montez à 140 pas et attendez la stabilisation. 1/M ≈ 0,20.</p><p>Extrapolez : entre 100 et 140 pas, 1/M a perdu 0,37, soit ~0,009 par pas. Il reste 0,20, donc environ 20 pas : <b>cote critique estimée ≈ 160 pas</b>. L'efficacité des grappes n'étant pas linéaire (courbe en S), l'estimation se corrigera en approchant.</p>",ok:(s,c,k)=>{ if(s.rods.R.p>=139.5&&Math.abs(s.rate)<0.0015) k.st=(k.st||0)+DT; else k.st=0; return k.st>20; }},
 {t:'R à 160 pas',tab:'cmd',h:"<p>Montez à 160 pas. Près de la criticité, la stabilisation devient très lente : plusieurs minutes simulées. 1/M ≈ 0,05 : la nouvelle extrapolation donne <b>≈ 166 pas</b>.</p><p><b>Attention à P6.</b> Le comptage approche maintenant de 10³ c/s : le permissif <b>P6</b> (GI > 10⁻¹⁰ A) peut apparaître dès cette étape. À son apparition, inhibez tout de suite la gamme source (Agir › Protection › <kbd>Inhiber GS</kbd>), sans attendre l'étape « Inhibez la gamme source ».</p>",ok:(s,c,k)=>{ if(s.rods.R.p>=159.5&&Math.abs(s.rate)<0.0012) k.st=(k.st||0)+DT; else k.st=0; return k.st>20; }},
 {t:'Divergez par pas de 2',tab:'cmd',h:"<p>Extrayez par <kbd>+1</kbd> ou <kbd>+2</kbd> en attendant chaque fois. Quand le comptage ne se stabilise plus et qu'un <b>temps de doublement constant</b> apparaît, le réacteur est critique, légèrement surcritique. Visez un Td de 60 à 120 s, jamais sous 20 s.</p><p>Pendant cette étape, <b>P6 apparaît</b> si ce n'est déjà fait : inhibez la gamme source dès l'alarme (Agir › Protection › <kbd>Inhiber GS</kbd>). Sinon, la puissance continue de monter et l'AAR « haut flux gamme source » tombe à 10⁵ c/s, deux décades plus haut : à ×10, cela peut aller vite.</p>",
  ok:(s,c,k)=>{ if(s.Td<300&&s.Td>15&&s.n>2e-8) k.st=(k.st||0)+DT; else k.st=0; return k.st>30; }},
 {t:'Inhibez la gamme source à P6',tab:'cmd',h:"<p>Quand l'alarme <b>P6</b> apparaît (GI > 10⁻¹⁰ A), appuyez sur <kbd>Inhiber GS</kbd> dans Protection. Sinon l'AAR tombera à 10⁵ c/s. Si vous l'avez déjà fait à l'étape précédente, cette étape est validée d'office.</p><p>Pourquoi on inhibe : les compteurs de la gamme source, très sensibles, sont faits pour l'arrêt. Au-delà de P6, la gamme intermédiaire couvre la suite ; on coupe donc le seuil d'arrêt de la gamme source (et, sur une vraie tranche, sa haute tension) pour qu'ils ne saturent pas.</p>",ok:s=>s.srInhib},
 {t:'Stabilisez entre 1 et 3 %',h:"<p>Laissez la puissance monter. Vers 1 %, le Doppler apparaît et ralentit la montée. Ajustez R de 1 ou 2 pas pour stabiliser entre 1 et 3 % : un temps de doublement de plus de 5 minutes, ou une décroissance aussi lente, suffit. Tenez 30 secondes.</p><p>Astuce : laissez agir le Doppler entre deux corrections ; chaque pas de R vaut ici environ 5 pcm.</p>",
  ok:(s,c,k)=>{ if(s.n>=0.01&&s.n<=0.03&&Math.abs(s.rate)<Math.LN2/300) k.st=(k.st||0)+DT; else k.st=0; return k.st>30; },
  sub:[['Puissance entre 1 et 3 %',s=>s.n>=0.01&&s.n<=0.03],['Évolution lente (|Td| > 5 min)',s=>Math.abs(s.rate)<Math.LN2/300],['30 s tenues',(s,c,k)=>(k.st||0)>30]]},
 {t:'Leçon terminée',h:"<p>Vous avez réalisé une divergence complète. Tentez maintenant l'exercice <b>Divergence</b> non guidé, qui est noté.</p><p><b>Et le seuil bas ?</b> Le seuil bas de haut flux (25 % PN) ne gêne pas ici : on reste sous 3 %. On le bloque plus tard, à l'apparition du permissif <b>P10</b> (10 %), pendant la montée en puissance : c'est l'exercice « Couplage et montée en charge ».</p>",last:true}
 ]},
{id:'div',kind:'exo',title:'Divergence',desc:"Approche sous-critique et premier critique depuis l'arrêt à chaud.",diff:2,speed:5,
 init:{P:0,critR:170,R:0,G:'cal',SD:225,coupled:false,xe:0,modeR:'man',modeG:'man'},
 brief:"<p>Arrêt à chaud : 286 °C, 155 bar, groupes d'arrêt extraits, GCP à la position de calibrage 0 %, groupe R inséré. Le bore a été ajusté : la <b>position critique estimée</b> est <b>R = 170 pas (± 25)</b>.</p><p>Extrayez R par paliers et surveillez le comptage gamme source. L'indicateur <b>1/M</b> (comptage initial ÷ comptage actuel) tend vers 0 à l'approche de la criticité : extrapolez-le.</p>",
 tips:"Conseil : ×5 pendant l'approche, ×10 après la criticité. Inhiber la gamme source avant 10⁵ c/s, sinon AAR.",
 obj:[
  {id:'crit',t:'Atteindre la criticité et franchir P6 (GI > 10⁻¹⁰ A)',w:"Le réacteur entretient seul la réaction en chaîne. Au-delà de P6, la gamme intermédiaire prend le relais de la gamme source.",test:s=>s.n>1e-7},
  {id:'inh',t:'Inhiber la gamme source',w:"Les compteurs de la gamme source saturent vers 10⁵ c/s ; s'ils restent en service, ils provoquent un AAR.",test:s=>s.srInhib},
  {id:'stab',t:'Stabiliser entre 1 et 3 % PN pendant 2 minutes',w:"Vers 1 %, le Doppler apparaît et freine seul la montée : c'est l'état d'attente avant le couplage.",test:(s,c)=>(c.k.stab||0)>=120}
 ],
 update(s,c){ if(c.k.cps0==null) c.k.cps0=s.n*1e10; if(s.n>=0.01&&s.n<=0.03&&Math.abs(s.rate)<Math.LN2/600) c.k.stab=(c.k.stab||0)+DT; else c.k.stab=0; },
 info(s,c){ const cps=s.n*1e10; return s.srInhib?('GI '+sci(s.n*1e-3)+' A · GP '+fmt(s.n*100,2)+' %'):('GS '+fmt(cps,0)+' c/s · 1/M = '+fmt(c.k.cps0/cps,3)); },
 end:(s,c)=>c.o.stab||(s.tripped&&s.t-s.tripT>20),
 evaluate(s,c){ return [Cr('Criticité atteinte',c.o.crit),Cr('Gamme source inhibée avant le seuil',c.o.inh&&!c.st.aar),Cr('Puissance stabilisée 1–3 %',c.o.stab),Cr('Temps de doublement jamais sous 20 s',c.st.minTd>=20,'Minimum : '+(Number.isFinite(c.st.minTd)?fmt(c.st.minTd,0)+' s':'—')),Cr("Pas d'AAR",!c.st.aar,c.st.aar?c.st.aar.cause:''),...common(s,c)]; },
 expected:"Approche par paliers : extraire R de 20 à 30 pas, attendre la stabilisation du comptage (multiplication sous-critique), relever 1/M et extrapoler vers zéro pour estimer la position critique. Réduire les pas près de la criticité. Au-delà, viser un temps de doublement d'au moins 60 s. À P6, inhiber la gamme source, puis laisser monter jusqu'au point d'échauffement nucléaire (1 à 3 %), où le Doppler stabilise seul la puissance ; ajuster R de quelques pas."},
{id:'montee',kind:'exo',title:'Couplage et montée en charge',desc:"Coupler l'alternateur et monter de 12 à 100 % à 3 %/min.",diff:2,speed:5,
 init:{P:.12,xe:.12,R:175,G:'cal',coupled:false,modeR:'man',modeG:'man'},
 brief:"<p>Le réacteur est à 12 % PN, la vapeur part au condenseur par le GCT-c. Couplez, passez les groupes en automatique et montez à 100 % <b>sans dépasser 3 %/min</b>.</p><p>Critères : Tmoy à ± 2 °C de Tref, ΔI dans le domaine, groupe R au-dessus de sa limite basse (150 pas).</p>",
 tips:"Juste après le couplage, montez la charge vers 13–14 % pour égaler la puissance du réacteur. À ce bore, les GCP compensent un peu trop le défaut de puissance (environ 200 pcm au passage en automatique) : passez d'abord les GCP en automatique en lançant une borication d'environ 1 m³, puis R quand Tmoy est revenue sur Tref. Corrigez ensuite au fil de la montée (borication si R descend, dilution s'il monte). Si la puissance repasse sous 10 %, rebloquez le seuil bas à P10. ×5 conseillé.",
 obj:[
  {id:'cpl',t:"Coupler l'alternateur au réseau",w:"L'alternateur est raccordé au réseau : la turbine commence à prendre de la vapeur et à produire de l'électricité.",test:s=>s.coupled},
  {id:'auto',t:'Passer R et GCP en automatique',w:"En mode G, les GCP suivent la charge et R tient la température : le réacteur suit la turbine.",test:s=>s.coupled&&s.modeR==='auto'&&s.modeG==='auto'},
  {id:'p100',t:'Atteindre 100 % de charge',w:"Une montée progressive limite les contraintes thermiques sur le combustible et laisse le temps de corriger au bore.",test:s=>s.Lt>=0.995}
 ],
 win:(s,c)=>s.coupled&&!s.tripped&&(!c||c.acts.couple==null||s.t-c.acts.couple>90),tol:2,
 update(s,c){ if(s.coupled&&s.LtSet>s.Lt+0.001&&s.ramp>3) c.st.rampViol=true; },
 info:s=>'Charge '+fmt(s.Lt*100,1)+' % · R '+fmt(s.rods.R.p,0)+' pas · Tmoy−Tref '+sgn(s.Tavg-s.Tref,1)+' °C',
 end:(s,c)=>(c.o.p100&&s.t-c.o.p100>60)||(s.tripped&&s.t-s.tripT>30),
 evaluate(s,c){ const st=c.st,q=x=>st.tw>0?x/st.tw:0; return [Cr('Turbine couplée',c.o.cpl),Cr('Groupes en automatique',c.o.auto),Cr('100 % atteint',c.o.p100),Cr('Vitesse ≤ 3 %/min respectée',!st.rampViol),Cr('Tmoy à ±2 °C de Tref ≥ 95 % du temps (après le couplage)',q(st.tT)>=0.95,fmt(q(st.tT)*100,0)+' %'),Cr('ΔI dans le domaine ≥ 90 % du temps',q(st.tDI)>=0.9,fmt(q(st.tDI)*100,0)+' %'),Cr('R jamais sous 150 pas',!st.rLow),Cr("Pas d'AAR",!st.aar,st.aar?st.aar.cause:''),...common(s,c)]; },
 expected:"Coupler vers 10–12 %, passer R et GCP en automatique (mode G) puis monter à 3 %/min. Les GCP suivent la courbe de calibrage ; l'écart entre leur efficacité et le défaut de puissance réel (qui dépend du bore via le coefficient modérateur), ainsi que l'évolution du xénon, se corrigent au bore. Ici les GCP sur-compensent : sans action, R descend sous sa limite basse et ΔI sort du domaine. Une borication lancée tôt et dosée garde R vers 180–200 pas et Tmoy sur Tref."},
{id:'suivi',kind:'exo',title:'Suivi de charge et xénon',desc:"Baisser à 50 %, tenir deux heures, remonter. Gérer le xénon au bore.",diff:3,speed:60,
 init:P100,
 brief:"<p>Pleine puissance, xénon à l'équilibre. Le dispatching demande : baisse à <b>50 % à 5 %/min</b>, palier de <b>2 heures</b>, puis retour à 100 %.</p><p>Critères : Tmoy à ±1,5 °C de Tref, ΔI dans le domaine, R dans sa bande 150–220 pas.</p>",
 tips:"Le xénon monte plusieurs heures après une baisse de puissance : il faut diluer. Au début du palier, il consomme environ 5 pcm/min, alors qu'une dilution à 10 m³/h n'en apporte qu'environ 4 : diluez à 20 ou 30 m³/h. À la remontée il brûle : il faut borer. ×60 pendant le palier.",
 obj:[
  {id:'low',t:'Baisser la charge à 50 %',w:"Le réseau demande moins d'électricité (nuit, week-end) : la tranche module sa production.",test:s=>s.Lt<=0.505},
  {id:'hold',t:'Tenir 50 % pendant 2 h',w:"Pendant ce palier, le xénon évolue pendant des heures : c'est lui qu'il faut compenser au bore.",test:(s,c)=>(c.k.hold||0)>=7200},
  {id:'up',t:'Remonter à 100 %',w:"À la remontée, le flux brûle le xénon : il libère de la réactivité qu'il faut reprendre en borant.",test:(s,c)=>c.o.hold&&s.Lt>=0.995}
 ],
 win:s=>s.coupled&&!s.tripped,tol:1.5,
 update(s,c){ if(c.o.low&&Math.abs(s.Lt-0.5)<0.02) c.k.hold=(c.k.hold||0)+DT; },
 info:(s,c)=>'Palier '+dur(c.k.hold||0)+' / 2 h · ρXe '+fmt(s.rho.xe,0)+' pcm · R '+fmt(s.rods.R.p,0)+' pas',
 end:(s,c)=>(c.o.up&&s.t-c.o.up>30)||(s.tripped&&s.t-s.tripT>30),
 evaluate(s,c){ const st=c.st,q=x=>st.tw>0?x/st.tw:0; return [Cr('Baisse à 50 % réalisée',c.o.low),Cr('Palier de 2 h tenu',c.o.hold),Cr('Retour à 100 %',c.o.up),Cr('Tmoy à ±1,5 °C de Tref ≥ 95 % du temps',q(st.tT)>=0.95,fmt(q(st.tT)*100,0)+' %'),Cr('ΔI dans le domaine ≥ 90 % du temps',q(st.tDI)>=0.9,fmt(q(st.tDI)*100,0)+' %'),Cr('R dans la bande 150–220 pas ≥ 90 % du temps',q(st.tR)>=0.9,fmt(q(st.tR)*100,0)+' %'),Cr("Pas d'AAR",!st.aar),...common(s,c)]; },
 expected:"Pendant la baisse, les GCP s'insèrent et R règle. Le xénon passe par un maximum plusieurs heures après la baisse : la réactivité perdue doit être compensée par dilution pour garder R dans sa bande et ΔI dans le domaine. À la remontée, le xénon est brûlé plus vite qu'il ne se forme : il faut borer. Les meilleurs résultats viennent d'appoints précoces et suffisants : au début du palier, le xénon consomme environ 5 pcm/min, ce qui demande une dilution de 20 à 30 m³/h ; à 10 m³/h, R reste bloqué en butée haute."},
{id:'arret',kind:'exo',title:"Mise à l'arrêt à chaud",desc:'Réduire, découpler, rendre sous-critique et borer à la marge.',diff:2,speed:5,
 init:{P:.3,xe:.3,R:190,G:'cal',coupled:true,modeR:'auto',modeG:'auto'},
 brief:"<p>Tranche à 30 %. Mettez le réacteur à l'arrêt à chaud de façon contrôlée : baisse de charge, découplage, passage sous-critique avec les groupes de commande, borication jusqu'à une <b>marge d'arrêt de 3 000 pcm</b> (groupes d'arrêt restant extraits), Tmoy stabilisée à 286 °C.</p>",
 tips:"Découplage possible sous 6 % de charge. Les groupes passent alors en manuel : insérez GCP et R. La marge d'arrêt est −ρ total.",
 obj:[
  {id:'l5',t:'Réduire la charge à 5 %',w:"On ramène la turbine à son minimum avant de la séparer du réseau.",test:s=>s.coupled&&s.Lt<=0.055||(!s.coupled&&!s.tripped)},
  {id:'dec',t:'Découpler la turbine',w:"La vapeur part alors au condenseur par le GCT-c, qui tient la pression des GV.",test:s=>!s.coupled&&!s.tripped},
  {id:'sub',t:'Puissance nucléaire sous 0,1 % PN',w:"Insérer GCP puis R rend le réacteur sous-critique : la puissance décroît avec une période d'environ −80 s.",test:s=>s.n<0.001},
  {id:'mar',t:"Marge d'arrêt ≥ 3 000 pcm",w:"Le bore garantit que le réacteur restera sous-critique même quand le xénon aura disparu, dans un ou deux jours.",test:s=>-s.rho.tot>=3000},
  {id:'tm',t:'Tmoy stabilisée à 286 ± 2 °C',w:"Le GCT-c tient 70 bar dans les GV, ce qui fixe Tmoy vers 286 °C : c'est l'arrêt à chaud.",test:s=>!s.coupled&&s.n<0.001&&Math.abs(s.Tavg-286)<2}
 ],
 info:s=>'Marge d\'arrêt '+fmt(-s.rho.tot,0)+' pcm · Bore '+fmt(s.Cb,0)+' ppm',
 end:(s,c)=>(c.o.l5&&c.o.dec&&c.o.sub&&c.o.mar&&c.o.tm)||c.st.isT!=null,
 evaluate(s,c){ return [Cr('Charge réduite à 5 %',c.o.l5),Cr('Turbine découplée',c.o.dec),Cr('Réacteur sous-critique',c.o.sub),Cr("Marge d'arrêt ≥ 3 000 pcm",c.o.mar,fmt(-s.rho.tot,0)+' pcm'),Cr('Tmoy stabilisée',c.o.tm),Cr('Arrêt contrôlé sans AAR',!c.st.aar,c.st.aar?c.st.aar.cause:''),...common(s,c)]; },
 expected:"Baisser la charge à 5–10 %/min, découpler sous 6 %, insérer GCP puis R en manuel jusqu'à la sous-criticité (la puissance décroît avec une période de −80 s), puis borer. La marge d'arrêt doit couvrir la disparition du xénon dans les jours suivants et un éventuel refroidissement : on bore au-delà du strict nécessaire."},
{id:'essaidg',kind:'exo',title:'Essai périodique des diesels',desc:"Démarrer chaque diesel, le laisser tourner 5 minutes, l'arrêter. Un à la fois.",diff:1,speed:5,init:P100,
 brief:"<p>Pleine puissance, tout est normal. Comme chaque mois sur une vraie tranche, vous allez vérifier que les deux <b>diesels de secours</b> démarrent et tiennent leur tension et leur fréquence.</p><p>Commandes dans la vue <b>Électrique</b> (onglet sous la vue centrale). Un diesel à la fois, pour ne jamais toucher aux deux voies en même temps.</p>",
 tips:"×5 conseillé. Le diesel met environ 10 s à démarrer ; il tourne ensuite sans reprendre le tableau, que le TS alimente toujours.",
 obj:[
  {id:'sA',t:'Démarrer le diesel A',w:"Il doit être en service en une dizaine de secondes, comme le jour où il faudra vraiment.",test:s=>s.el.dg.A.st==='service'},
  {id:'rA',t:'Le laisser tourner 5 minutes',w:"On vérifie qu'il tient 6,6 kV et 50 Hz dans la durée, pas seulement qu'il démarre.",test:(s,c)=>(c.k.runA||0)>=300},
  {id:'pA',t:'Arrêter le diesel A',w:"Il revient « prêt » : il redémarrera seul au prochain manque de tension.",test:(s,c)=>c.o.rA!=null&&s.el.dg.A.st==='pret'},
  {id:'sB',t:'Démarrer le diesel B',test:(s,c)=>c.o.pA!=null&&s.el.dg.B.st==='service'},
  {id:'rB',t:'Le laisser tourner 5 minutes',test:(s,c)=>(c.k.runB||0)>=300},
  {id:'pB',t:'Arrêter le diesel B',test:(s,c)=>c.o.rB!=null&&s.el.dg.B.st==='pret'}
 ],
 update(s,c){ const d=s.el.dg; if(d.A.st==='service') c.k.runA=(c.k.runA||0)+DT; if(d.B.st==='service') c.k.runB=(c.k.runB||0)+DT; if(d.A.st!=='pret'&&d.B.st!=='pret') c.k.both=true; },
 info(s,c){ const d=s.el.dg, x=k=>({pret:'prêt',demarrage:'démarrage',service:'en service',defaut:'défaut'})[d[k].st]; return 'Diesel A '+x('A')+' · '+dur(c.k.runA||0)+' · diesel B '+x('B')+' · '+dur(c.k.runB||0); },
 end:(s,c)=>c.o.pB!=null||s.t>3600||(c.st.aar&&s.t-c.st.aar.t>30),
 evaluate(s,c){ return [Cr('Diesel A essayé (démarrage, 5 min, arrêt)',c.o.pA!=null),Cr('Diesel B essayé (démarrage, 5 min, arrêt)',c.o.pB!=null),Cr('Un seul diesel en essai à la fois',!c.k.both),Cr('Les deux diesels prêts à la fin',s.el.dg.A.st==='pret'&&s.el.dg.B.st==='pret'),Cr("Pas d'AAR",!c.st.aar),...common(s,c)]; },
 expected:"L'essai périodique vérifie qu'un matériel de sûreté, qui ne sert presque jamais, marchera le jour où il le faudra. On démarre le diesel, on contrôle tension et fréquence, on le laisse tourner, puis on le remet en attente. Une voie à la fois : pendant l'essai, l'autre voie reste intacte. Sur une vraie tranche, l'essai va plus loin : le diesel est couplé au tableau en parallèle du réseau et chargé progressivement. Le simulateur se limite au démarrage, à la marche et à l'arrêt."},
{id:'h3',kind:'exo',title:'Perte totale des sources électriques',desc:"Réseaux et deux diesels perdus : la situation « H3 ». Tenir avec la vapeur et les batteries, puis le DUS.",diff:3,speed:2,init:P100,
 brief:"<p>Pleine puissance. Dans une minute, les réseaux 400 et 225 kV vont disparaître, l'îlotage échouera et <b>les deux diesels refuseront de démarrer</b> : plus aucun tableau secouru sous tension.</p><p>Il reste la turbopompe ASG, entraînée par la vapeur des GV, les batteries, le turboalternateur LLS et le <b>diesel d'ultime secours (DUS)</b>. À vous de rétablir une voie.</p>",
 tips:"La vue Électrique montre les sources et les batteries. Le DUS met environ 2 minutes à prendre son tableau.",
 obj:[
  {id:'h3',t:'Constater la perte des deux voies secourues',w:"Diesels « déclenchés », LHA et LHB hors tension : c'est la situation H3.",test:(s,c)=>c.k.f!=null&&s.el.dg.A.st==='defaut'&&s.el.dg.B.st==='defaut'},
  {id:'tps',t:'Vérifier que la turbopompe ASG alimente les GV',w:"Sans courant, seule la vapeur peut encore pousser l'eau dans les GV : c'est elle qui évacue la puissance résiduelle.",test:(s,c)=>c.o.h3!=null&&s.Wasg>0.005},
  {id:'dus',t:'Démarrer le diesel d\'ultime secours',w:"Le DUS, ajouté après Fukushima, est protégé contre les agressions extrêmes et peut reprendre l'une ou l'autre voie.",test:(s,c)=>c.acts.dus!=null},
  {id:'voie',t:'Une voie secourue réalimentée',test:s=>s.el.src.LHA==='dus'||s.el.src.LHB==='dus'},
  {id:'chg',t:'Charge RCV et injection de sécurité de nouveau disponibles',w:"Les charges reprennent par paliers : IS après 5 s, charge RCV après 30 s.",test:(s,c)=>c.o.voie!=null&&s.el.av.chg===1&&s.el.av.is===1}
 ],
 update(s,c){ if(c.k.t0==null) c.k.t0=s.t;
  if(c.k.f==null&&s.t-c.k.t0>=60){ c.k.f=s.t; s.grid=false; s.el.r225=false; if(s.coupled) s.ilot=true; s.el.ilotRate=true; s.el.dg.A.fail=true; s.el.dg.B.fail=true; }
  if(c.k.f!=null) c.k.minBat=Math.min(c.k.minBat==null?1:c.k.minBat,s.el.bat); },
 info(s){ const e=s.el; return 'LHA '+(e.src.LHA||'hors tension')+' · LHB '+(e.src.LHB||'hors tension')+' · batteries '+fmt(e.bat*100,0)+' % · ASG '+fmt(s.Wasg*100,1)+' % · niveau GV '+fmt(s.Lsg,0)+' %'; },
 end:(s,c)=>(c.o.chg!=null&&s.t-c.o.chg>60)||(c.k.f!=null&&s.t-c.k.f>2400),
 evaluate(s,c){ return [Cr('DUS démarré en moins de 10 min',c.acts.dus!=null&&c.k.f!=null&&c.acts.dus-c.k.f<=600,c.acts.dus!=null&&c.k.f!=null?'En '+dur(c.acts.dus-c.k.f):'Non réalisé'),Cr('Une voie secourue réalimentée',c.o.voie!=null),Cr('Niveau GV resté au-dessus de 15 %',c.af.minLsg>15,'Minimum '+fmt(c.af.minLsg,1)+' %'),Cr('Batteries jamais épuisées',(c.k.minBat==null?1:c.k.minBat)>0.05,'Minimum '+fmt((c.k.minBat==null?1:c.k.minBat)*100,0)+' %'),...common(s,c)]; },
 expected:"En H3, plus aucun tableau secouru n'est sous tension : ni IS, ni charge RCV, ni motopompe ASG. Le refroidissement tient grâce à la <b>turbopompe ASG</b>, entraînée par la vapeur des GV, et à la vapeur évacuée à l'atmosphère par le GCT-a. Les <b>batteries</b> gardent le contrôle-commande pendant environ une heure ; le <b>turboalternateur LLS</b> démarre pour l'injection aux joints des pompes primaires. La priorité est de rétablir une voie : démarrer le <b>DUS</b>, qui reprend un tableau secouru en deux minutes environ, puis laisser les charges redémarrer par paliers. Fukushima a montré que cette situation, jugée extrêmement improbable, devait être préparée : c'est l'origine du DUS et de la FARN."},
{id:'tpa',kind:'alea',title:"Perte d'une turbopompe alimentaire",desc:"À 100 %, une TPA déclenche : la capacité d'alimentation tombe à 58 %.",diff:3,speed:1,init:P100,
 fire:s=>{s.tpa[1]=false;},hints:["Le niveau GV baisse et l'alarme « écart débit ARE / vapeur » apparaît : l'eau qui entre ne compense plus la vapeur qui sort.","C'est l'eau alimentaire : regardez les voyants des turbopompes dans la carte « Eau alimentaire »."],hint:"Débit d'eau alimentaire limité : il faut réduire très vite la charge turbine (vitesse 30 %/min) et renforcer l'alimentation.",
 update(s,c){ if(c.fired&&c.k.red==null&&s.Lt<=0.60) c.k.red=s.t; },
 end:(s,c)=>c.fired&&((s.t-c.fired>600)||(c.st.aar&&s.t-c.st.aar.t>60)),
 evaluate(s,c){ return [Cr("Pas d'AAR",!c.st.aar,c.st.aar?c.st.aar.cause:''),Cr('Charge réduite sous 60 % en moins de 3 min',c.k.red!=null&&c.k.red-c.fired<=180,c.k.red!=null?'En '+dur(c.k.red-c.fired):'Non réalisé'),Cr('Niveau GV resté au-dessus de 20 %',c.af.minLsg>20,'Minimum '+fmt(c.af.minLsg,1)+' %'),Cr('Motopompe APD démarrée',s.apd),...common(s,c)]; },
 expected:"Sur perte d'une TPA à pleine puissance, l'ARE ne peut plus fournir que ~58 % du débit nominal. Il faut réduire immédiatement la charge (baisse rapide 30 %/min vers 50–55 %) et démarrer la motopompe APD. La contraction du niveau GV lors de la baisse de charge aggrave la baisse de niveau : chaque seconde compte. Les groupes en automatique suivent la baisse."},
{id:'ilot',kind:'alea',title:'Îlotage sur perte du réseau',desc:'Le réseau disparaît : la turbine se cale sur les auxiliaires.',diff:3,speed:1,init:P100,
 fire:(s,c)=>{s.grid=false; if(s.coupled) s.ilot=true; c.k.back=s.t+360;},hints:["La charge turbine chute brutalement vers 5 % alors que vous n'avez rien demandé ; le GCT-c s'ouvre.","C'est le réseau électrique : regardez le disjoncteur et l'état « Îlotage » dans le synoptique et l'alarme correspondante."],hint:"La vapeur part au condenseur par le GCT-c pendant que les groupes s'insèrent. Surveillez pression pressu et Tmoy, laissez R se recaler. Ensuite le xénon s'accumule : quand R approche de sa butée haute, diluez par petits volumes (1 m³ à 30 m³/h) pour garder Tmoy sur Tref. Recouplez au retour du réseau.",
 update(s,c){ if(c.k.back&&!s.grid&&s.t>=c.k.back){ s.grid=true; logEv(s,'auto','Réseau de nouveau disponible'); } },
 end:(s,c)=>c.fired&&((c.acts.recouple&&s.t-c.acts.recouple>240)||s.t-c.fired>1500||(c.st.aar&&s.t-c.st.aar.t>60)),
 evaluate(s,c){ return [Cr("Pas d'AAR",!c.st.aar,c.st.aar?c.st.aar.cause:''),Cr('Pas d\'ouverture de soupape SEBIM',!c.st.sebim),Cr('Recouplage au réseau effectué',c.acts.recouple!=null),Cr('Tmoy recalée (±2 °C) en fin d\'essai',s.coupled&&Math.abs(s.Tavg-s.Tref)<2),...common(s,c)]; },
 expected:"La perte du réseau provoque un îlotage : la turbine se cale sur les auxiliaires (~5 %). Le GCT-c s'ouvre pour évacuer l'excédent de vapeur pendant que GCP et R s'insèrent. Surveiller l'aspersion (la pression monte), Tmoy et le niveau GV. La régulation compare aussi la puissance du réacteur à celle de la turbine : dès que la puissance passe sous la charge, R ressort, et Tmoy reste près de Tref. Ne pas borer. Dans les minutes qui suivent, le xénon s'accumule (la puissance a chuté alors que l'iode continue de se transformer en xénon) : R remonte jusqu'en butée haute, puis Tmoy décroche sous Tref, de 5 °C et plus si personne n'agit. Il faut alors diluer par petits volumes (environ 1 m³ à 30 m³/h toutes les deux à trois minutes) pour garder R dans sa bande et Tmoy sur Tref. Au retour du réseau, recoupler puis reprendre la charge progressivement."},
{id:'drop',kind:'alea',title:'Chute de grappe',desc:'Une grappe chute en cœur à pleine puissance.',diff:2,speed:5,init:P100,
 fire:s=>{s.dropped=true;},hints:["La puissance chute d'un coup, Tmoy passe sous Tref, la pression baisse ; l'extraction des grappes est bloquée.","C'est une grappe : regardez l'alarme rouge et le bilan de réactivité (ligne Grappes)."],hint:"−280 pcm, extraction bloquée. Passez les GCP en manuel, recalez Tmoy en réduisant la charge, puis repliez sous 50 % PN.",
 update(s,c){ if(!c.fired) return; const d=Math.abs(s.Tavg-s.Tref); if(d>1.5) c.k.dev=true; if(c.k.tok==null&&s.t-c.fired>30&&d<1.0&&(c.k.dev||s.t-c.fired>120)) c.k.tok=s.t; if(c.k.p50==null&&s.n<0.5) c.k.p50=s.t; },
 end:(s,c)=>c.fired&&((c.k.p50&&s.t-c.k.p50>120)||s.t-c.fired>2400||(c.st.aar&&s.t-c.st.aar.t>60)),
 evaluate(s,c){ return [Cr("Pas d'AAR",!c.st.aar,c.st.aar?c.st.aar.cause:''),Cr('Tmoy recalée sous 10 min',c.k.tok!=null&&c.k.tok-c.fired<=600,c.k.tok!=null?'En '+dur(c.k.tok-c.fired):'Non réalisé'),Cr('Repli sous 50 % PN en moins de 30 min',c.k.p50!=null&&c.k.p50-c.fired<=1800,c.k.p50!=null?'En '+dur(c.k.p50-c.fired):'Non réalisé'),...common(s,c)]; },
 expected:"La chute d'une grappe apporte environ −280 pcm : la puissance baisse, Tmoy passe sous Tref, la pression pressu diminue. L'extraction des groupes est bloquée, la régulation ne peut pas recaler la température. Passer les GCP en manuel (sinon ils s'insèrent encore à chaque baisse de charge), puis réduire la charge turbine d'une vingtaine de % pour ramener Tmoy sur Tref, puis replier sous 50 % PN (déséquilibre radial de puissance) en attendant le diagnostic et la récupération de la grappe."},
{id:'spray',kind:'alea',title:'Aspersion bloquée ouverte',desc:'Une vanne d\'aspersion du pressuriseur reste ouverte.',diff:2,speed:1,init:P100,
 fire:s=>{s.sprayStuck=true;},hints:["La pression pressuriseur baisse régulièrement alors que les chaufferettes sont à fond.","C'est dans le pressuriseur : regardez l'ouverture de l'aspersion dans sa carte."],hint:"La pression baisse malgré le chauffage. Regardez l'aspersion dans Commandes › Pressuriseur.",
 end:(s,c)=>c.fired&&((c.acts.sprayIsol&&s.t-c.acts.sprayIsol>180)||s.t-c.fired>900||(c.st.aar&&s.t-c.st.aar.t>60)),
 evaluate(s,c){ return [Cr('Aspersion isolée',s.sprayIsol,c.acts.sprayIsol!=null?'En '+dur(c.acts.sprayIsol-c.fired):''),Cr('Pression restée au-dessus de 140 bar',c.af.minPp>140,'Minimum '+fmt(c.af.minPp,1)+' bar'),Cr("Pas d'AAR",!c.st.aar,c.st.aar?c.st.aar.cause:''),...common(s,c)]; },
 expected:"Une vanne d'aspersion restée ouverte condense la vapeur du pressuriseur plus vite que les chaufferettes ne la produisent : la pression chute d'environ 7 bar/min. Identifier l'aspersion anormale (ouverture à 100 % malgré une pression basse) et isoler la ligne avant l'AAR. À pleine puissance, c'est la protection ΔT surtempérature qui déclenche la première, vers 137 bar, car son seuil baisse avec la pression ; le seuil basse pression de 131 bar ne serait atteint qu'ensuite. Les chaufferettes de secours remontent ensuite la pression."},
{id:'leak',kind:'alea',title:'Fuite sur la décharge RCV',desc:'Fuite de 30 m³/h sur la ligne de décharge.',diff:2,speed:2,init:P100,
 fire:s=>{s.leakQ=30;s.leakType='letdown';},hints:["Le niveau pressuriseur baisse sans variation de température, le débit de charge monte et l'activité enceinte augmente.","C'est une perte d'eau du primaire : comparez charge et décharge dans la carte « Pressuriseur — RCV »."],hint:"La charge RCV compense une perte d'eau. La fuite est-elle sur une ligne qu'on peut isoler ?",
 end:(s,c)=>c.fired&&((c.acts.ldIsol&&s.t-c.acts.ldIsol>240)||s.t-c.fired>1500||(c.st.aar&&s.t-c.st.aar.t>60)),
 evaluate(s,c){ return [Cr('Décharge isolée en moins de 6 min',c.acts.ldIsol!=null&&c.acts.ldIsol-c.fired<=360,c.acts.ldIsol!=null?'En '+dur(c.acts.ldIsol-c.fired):'Non réalisé'),Cr('Niveau pressu resté au-dessus de 14 %',c.af.minLp>14,'Minimum '+fmt(c.af.minLp,1)+' %'),Cr("Pas d'AAR",!c.st.aar,c.st.aar?c.st.aar.cause:''),...common(s,c)]; },
 expected:"Une fuite sur la ligne de décharge RCV se traduit par un débit de charge anormalement élevé, une baisse du niveau pressu et une activité enceinte qui monte. La fuite étant en aval des vannes d'isolement, isoler la décharge la supprime. La régulation de charge réduit ensuite le débit pour tenir le niveau."},
{id:'are',kind:'alea',title:'Défaillance de la régulation ARE',desc:'La régulation d\'eau alimentaire ouvre en grand.',diff:2,speed:1,init:P100,
 fire:s=>{s.areFail=true;},hints:["Le niveau GV monte régulièrement, au-delà de 60 %.","C'est l'eau alimentaire : comparez le débit ARE et le débit vapeur dans la carte « Eau alimentaire »."],hint:"Le débit d'eau alimentaire dépasse le débit vapeur. Reprenez la main sur l'ARE.",
 end:(s,c)=>c.fired&&((c.acts.areMan&&s.t-c.acts.areMan>300)||s.t-c.fired>900||(c.st.turbTrip!=null&&s.t-c.st.turbTrip>60)),
 evaluate(s,c){ return [Cr('ARE passée en manuel',c.acts.areMan!=null,c.acts.areMan!=null?'En '+dur(c.acts.areMan-c.fired):''),Cr('Niveau GV resté sous 75 %',c.af.maxLsg<75,'Maximum '+fmt(c.af.maxLsg,1)+' %'),Cr("Pas de déclenchement turbine ni d'AAR",c.st.turbTrip==null&&!c.st.aar),...common(s,c)]; },
 expected:"La régulation ARE défaillante ouvre les vannes en grand : le niveau GV monte vers le seuil très haut (80 %) qui isole l'ARE et déclenche la turbine, donc le réacteur. Passer l'ARE en manuel et régler un débit inférieur au débit vapeur, puis égal quand le niveau est revenu vers 50 %."},
{id:'dil',kind:'alea',title:'Dilution intempestive',desc:"Une vanne d'eau d'appoint reste ouverte sans demande.",diff:3,speed:5,init:P100,
 fire:s=>{s.dilFault=true;},hints:["Le groupe R descend lentement alors que la charge ne bouge pas.","C'est le bore : regardez sa concentration dans le bandeau et l'information « Appoint REA en service »."],hint:"R descend alors que la charge ne bouge pas. D'où vient la réactivité ajoutée ?",
 update(s,c){ if(c.acts.reaIsol!=null&&c.k.rb==null&&s.rods.R.p>=170) c.k.rb=s.t; },
 end:(s,c)=>c.fired&&((c.k.rb&&s.t-c.k.rb>60)||s.t-c.fired>5400||(c.st.aar&&s.t-c.st.aar.t>60)),
 evaluate(s,c){ return [Cr('Dilution isolée',c.acts.reaIsol!=null,c.acts.reaIsol!=null?'En '+dur(c.acts.reaIsol-c.fired):''),Cr('R jamais sous 130 pas',!c.st.rVeryLow),Cr('R ramené au-dessus de 170 pas',c.k.rb!=null),Cr("Pas d'AAR",!c.st.aar),...common(s,c)]; },
 expected:"Une dilution non demandée ajoute de la réactivité lentement (environ 10 pcm/min ici). En automatique, R s'insère pour compenser et descend vers ses limites. Indices : 'Appoint REA en service' sans demande, bore qui baisse, R qui descend sans variation de charge. Isoler l'appoint REA, puis borer pour remonter R dans sa bande."},
{id:'rodwd',kind:'alea',title:'Retrait incontrôlé à puissance nulle',desc:'Le groupe R s\'extrait seul juste après la divergence.',diff:3,speed:1,
 init:{P:1e-5,critR:110,R:110,G:'cal',coupled:false,xe:0,modeR:'man',modeG:'man'},
 fire:s=>{s.rodWd=true;},hints:["Le temps de doublement raccourcit vite, la puissance monte sans que vous ayez rien touché.","Ce sont les grappes : regardez la position du groupe R dans la carte « Grappes de commande »."],hint:"Le temps de doublement s'effondre et le groupe R bouge sans commande. Le passage en manuel ne suffira pas.",
 update(s,c){ if(c.fired&&c.k.al==null&&s.Td<20) c.k.al=s.t; },
 end:(s,c)=>c.st.aar&&s.t-c.st.aar.t>30,
 evaluate(s,c){ const a=c.st.aar; return [Cr('AAR manuel avant la protection automatique',a&&a.src==='op',a?(a.src==='op'?'Réaction en '+dur(a.t-(c.k.al||c.fired))+' après l\'alarme':a.cause):''),Cr('Puissance maximale sous 25 % PN',c.st.maxN<0.25,'Maximum '+fmt(c.st.maxN*100,2)+' %'),...common(s,c)]; },
 expected:"Un défaut du système de commande extrait le groupe R en continu (environ 8 pcm/s). Le passage en manuel est sans effet. À puissance nulle il n'y a pas encore de contre-réaction Doppler : le temps de doublement chute en quelques dizaines de secondes vers le prompt-critique. La seule parade est l'AAR manuel immédiat, avant le seuil bas haut flux (25 %)."},
{id:'gmpp',kind:'alea',title:"Déclenchement d'une pompe primaire",desc:'Une GMPP déclenche à pleine puissance : AAR puis stabilisation.',diff:2,speed:2,init:P100,
 fire:s=>{s.pumps[1]=false;},hints:["Le réacteur s'arrête automatiquement : lisez la cause de l'AAR dans le journal.","C'est le circuit primaire : regardez les voyants des pompes primaires et le débit dans le synoptique."],hint:"L'AAR est automatique. Vérifiez sa bonne exécution puis stabilisez : Tmoy, niveau GV, pressu. Réarmez l'AAR.",
 ok(s){ return Math.abs(s.Tavg-287)<3&&s.Lsg>35&&s.Lsg<65&&s.Ppzr>150&&s.Ppzr<158&&!s.tripped; },
 end(s,c){ return c.fired&&((s.t-c.fired>120&&this.ok(s))||s.t-c.fired>900); },
 evaluate(s,c){ return [Cr('Tmoy stabilisée entre 284 et 290 °C',Math.abs(s.Tavg-287)<3,fmt(s.Tavg,1)+' °C'),Cr('Niveau GV entre 35 et 65 %',s.Lsg>35&&s.Lsg<65,fmt(s.Lsg,1)+' %'),Cr('Pression pressu entre 150 et 158 bar',s.Ppzr>150&&s.Ppzr<158,fmt(s.Ppzr,1)+' bar'),Cr('AAR réarmé',!s.tripped),...common(s,c)]; },
 expected:"Le déclenchement d'une GMPP au-dessus de P7 provoque un AAR automatique sur bas débit. Ensuite : vérifier l'AAR (grappes en bas, puissance en décroissance), la turbine déclenchée, l'ASG en service, le GCT-c en mode pression qui tient ~70 bar dans les GV. Laisser Tmoy se stabiliser vers 286 °C, surveiller le niveau GV (contraction puis remplissage), la pression et le niveau pressu. Réarmer l'AAR quand plus aucun signal n'est présent."},
{id:'mdte',kind:'alea',title:'Perte des alimentations externes',desc:"Les réseaux 400 et 225 kV disparaissent et l'îlotage échoue : AAR, diesels, circulation naturelle.",diff:3,speed:2,init:P100,
 fire:(s,c)=>{ s.grid=false; s.el.r225=false; if(s.coupled) s.ilot=true; s.el.ilotRate=true; c.k.back=s.t+1200; },
 hints:["Le réacteur s'arrête, les pompes primaires et les turbopompes alimentaires s'arrêtent aussi, et beaucoup d'alarmes sonnent d'un coup.","C'est l'électricité : ouvrez la vue « Électrique » (onglet sous la vue centrale, ou la zone Alimentations du synoptique)."],
 hint:"Plus aucune source externe : les diesels reprennent les tableaux secourus en ~10 s. Vérifiez-les, puis la circulation naturelle et l'ASG.",
 update(s,c){ if(!c.fired) return; const e=s.el;
  if(c.k.dg==null&&e.src.LHA==='dg'&&e.src.LHB==='dg') c.k.dg=s.t;
  if(c.k.nc==null&&s.t-c.fired>300&&!s.pumps.some(Boolean)&&s.flow>0.02&&s.Thot-s.Tcold<45) c.k.nc=s.t;
  if(c.k.back&&!e.r225&&s.t>=c.k.back){ e.r225=true; logEv(s,'auto','Réseau 225 kV de nouveau disponible'); } },
 end:(s,c)=>c.fired&&s.t-c.fired>1500,
 evaluate(s,c){ return [Cr('Les deux diesels ont repris leur tableau',c.k.dg!=null,c.k.dg!=null?'En '+dur(c.k.dg-c.fired):'Non'),Cr('Circulation naturelle établie',c.k.nc!=null,'Débit '+fmt(s.flow*100,1)+' %, écart chaud − froid '+fmt(s.Thot-s.Tcold,0)+' °C'),Cr('Niveau GV resté au-dessus de 15 %',c.af.minLsg>15,'Minimum '+fmt(c.af.minLsg,1)+' %'),Cr('Pas d\'ouverture de soupape SEBIM',!c.st.sebim),Cr('Tmoy sous 300 °C en fin d\'essai',s.Tavg<300,fmt(s.Tavg,1)+' °C'),...common(s,c)]; },
 expected:"Sans réseau 400 kV, la tranche devrait s'îloter ; ici l'îlotage échoue, la turbine déclenche et le réacteur s'arrête (AAR sur déclenchement turbine au-dessus de P7). Le TS ne reçoit plus rien et le 225 kV est perdu aussi : c'est le <b>manque de tension externe</b>. Les tableaux normaux s'éteignent (GMPP, TPA, condenseur), les deux diesels démarrent et reprennent LHA et LHB en une dizaine de secondes, puis les charges redémarrent par paliers (IS, ASG, charge RCV, chaufferettes). Vérifier : AAR, diesels en service, ASG qui alimente les GV, vapeur évacuée par le GCT-a puisque le condenseur est perdu, et la <b>circulation naturelle</b> du primaire (écart chaud − froid élevé mais stable). Le 225 kV revient au bout de 20 minutes : les tableaux repassent sur le TA."},
{id:'dgko',kind:'alea',title:'Un diesel refuse de démarrer',desc:"Perte des alimentations externes, et le diesel A ne démarre pas : il faut réalimenter LHA.",diff:3,speed:2,init:P100,
 fire:(s,c)=>{ s.grid=false; s.el.r225=false; if(s.coupled) s.ilot=true; s.el.ilotRate=true; s.el.dg.A.fail=true; },
 hints:["Le réacteur s'arrête et les pompes primaires aussi. Dans le journal, un diesel signale un défaut.","C'est l'électricité : dans la vue « Électrique », un tableau secouru reste sans tension."],
 hint:"Le diesel A est en défaut : LHA reste sans tension. Une voie suffit, mais il n'y a plus de redondance. Quel autre moyen peut réalimenter un tableau secouru ?",
 end:(s,c)=>c.fired&&((c.acts.dus!=null&&s.el.src.LHA==='dus'&&s.t-c.acts.dus>200)||s.t-c.fired>1500),
 evaluate(s,c){ return [Cr('DUS démarré en moins de 5 min',c.acts.dus!=null&&c.acts.dus-c.fired<=300,c.acts.dus!=null?'En '+dur(c.acts.dus-c.fired):'Non réalisé'),Cr('LHA réalimenté par le DUS',s.el.src.LHA==='dus'),Cr('LHB tenu par le diesel B',s.el.src.LHB==='dg'),Cr('Niveau GV resté au-dessus de 15 %',c.af.minLsg>15,'Minimum '+fmt(c.af.minLsg,1)+' %'),Cr('Pas d\'ouverture de soupape SEBIM',!c.st.sebim),...common(s,c)]; },
 expected:"Même début que la perte des alimentations externes, mais le diesel A échoue : LHA reste sans tension. La voie B suffit à refroidir le cœur (une motopompe ASG, une file d'IS, la charge RCV), mais il ne reste plus aucune redondance. On constate l'échec dans la vue Électrique (diesel A « déclenché »), puis on démarre le <b>diesel d'ultime secours (DUS)</b>, qui peut reprendre l'une ou l'autre voie : il lui faut environ deux minutes. Sur une vraie tranche, la turbine à combustion du site serait une autre option ; le simulateur ne la représente pas."},
{id:'lhb',kind:'alea',title:'Perte du tableau secouru LHB',desc:'Un défaut met le tableau LHB hors tension à pleine puissance.',diff:2,speed:5,init:P100,
 fire:s=>{ s.el.def.LHB=true; },
 hints:["Rien ne bouge dans le bandeau, mais une alarme rouge est apparue.","Lisez l'alarme, puis ouvrez la vue « Électrique » : un tableau est sans tension."],
 hint:"La tranche tourne normalement, mais la voie B est perdue : il n'y a plus de redondance sur les systèmes de sûreté. Les règles imposent de replier.",
 update(s,c){ if(!c.fired) return; if(c.k.red==null&&s.LtSet<0.95) c.k.red=s.t; if(c.k.p50==null&&s.Lt<=0.505) c.k.p50=s.t; },
 end:(s,c)=>c.fired&&((c.k.p50&&s.t-c.k.p50>120)||s.t-c.fired>3000||(c.st.aar&&s.t-c.st.aar.t>60)),
 evaluate(s,c){ return [Cr('Repli engagé en moins de 10 min',c.k.red!=null&&c.k.red-c.fired<=600,c.k.red!=null?'En '+dur(c.k.red-c.fired):'Non réalisé'),Cr('Charge à 50 % en moins de 40 min',c.k.p50!=null&&c.k.p50-c.fired<=2400,c.k.p50!=null?'En '+dur(c.k.p50-c.fired):'Non réalisé'),Cr('Vitesse de baisse ≤ 5 %/min',s.ramp<=5),Cr("Pas d'AAR",!c.st.aar,c.st.aar?c.st.aar.cause:''),...common(s,c)]; },
 expected:"Un défaut sur le tableau LHB le met hors tension : la motopompe ASG B, la file B d'injection de sécurité, la charge RCV voie B et les chaufferettes secourues B sont perdues. En fonctionnement, rien ne change, car les tableaux normaux et la voie A suffisent. Mais un accident survenant maintenant ne trouverait plus qu'une seule voie : les règles d'exploitation imposent de <b>replier</b> la tranche dans un délai fixé. Repérer l'alarme, confirmer dans la vue Électrique, puis engager une baisse de charge calme (3 à 5 %/min). Le simulateur s'arrête à 50 %."},
{id:'tmi',kind:'histo',title:'Three Mile Island, à votre place',desc:"L'accident de TMI-2 (1979) transposé sur notre tranche : mêmes pannes, mêmes indications trompeuses. Trouverez-vous la fuite ?",diff:3,speed:1,init:P100,
 brief:"<p>Le 28 mars 1979 à 4 h du matin, la tranche 2 de Three Mile Island (Pennsylvanie) perd son eau alimentaire. Une soupape de décharge du pressuriseur s'ouvre puis reste bloquée ouverte, alors que son voyant indique « fermée ». En moins de trois heures, environ la moitié du cœur fond.</p><p>Le scénario rejoue ces pannes sur notre REP 900, à pleine puissance. Il y a des différences avec la centrale américaine : nos GV gardent plus d'eau, et la pression n'irait pas assez haut pour ouvrir seule une soupape. Celle-ci s'ouvre donc de force au pic de pression.</p><p>Vous êtes l'opérateur. Aucune indication sur la nature de l'accident : à vous de comprendre ce qui se passe, avec les instruments choisis ci-dessous. Accélérez une fois la situation comprise : l'accident se joue sur deux à trois heures.</p>",
 hints:["La pression baisse alors que le niveau du pressuriseur monte, et la ligne de décharge du pressuriseur est chaude.","C'est en tête du pressuriseur : une soupape peut être ouverte alors que son voyant indique « fermée »."],
 hint:"Fermez la vanne d'isolement de la soupape (carte Pressuriseur), laissez l'injection de sécurité à plein débit et gardez les pompes primaires : avec autant de vapeur dans le circuit, les arrêter maintenant découvrirait le cœur.",
 fire:(s,c)=>{ s.tmi=true; s.tpa=[false,false]; s.asgV=false; c.k.pk=s.Ppzr; c.k.p0=s.Ppzr; c.k.chain=[]; },
 update(s,c){ if(c.fired==null) return; const k=c.k;
  /* la soupape s'ouvre au pic de pression qui suit l'AAR, puis reste bloquée : l'ordre retombe, la soupape non */
  if(!s.porvStuck){ k.pk=Math.max(k.pk,s.Ppzr); if(s.tripped&&s.Ppzr<k.pk-0.3){ s.porvStuck=true; s.porvOpen=true; logEv(s,'alarm','Alarme : Soupape pressu SEBIM ouverte'); logEv(s,'auto','Soupape pressu SEBIM : ordre de fermeture envoyé'); } }
  if(k.satT==null&&s.sat) k.satT=s.t;
  if(k.isCut==null&&s.is&&s.isThr<1&&s.satMargin<10&&!s.porvIsol) k.isCut=s.t;
  if(k.pmpCut==null&&s.sat&&s.pumps.some(p=>!p)){ k.pmpCut=s.t; k.pmpCutA=s.alpha; }
  if(k.burstT==null&&s.rdpBurst) k.burstT=s.t;
  if(k.uncT==null&&s.unc>0) k.uncT=s.t;
  k.maxUnc=Math.max(k.maxUnc||0,s.unc);
  if(k.dmgT==null&&s.coreDmg>=3) k.dmgT=s.t;
  if(s.porvIsol&&s.satMargin>3&&s.unc===0){ if(k.safeT==null) k.safeT=s.t; } else k.safeT=null;
  tmiChain(s,c); },
 end:(s,c)=>c.fired!=null&&((c.k.safeT!=null&&s.t-c.k.safeT>600)||(c.k.dmgT!=null&&s.t-c.k.dmgT>600)||s.t-c.fired>4*3600),
 info:(s,c)=>c.fired==null?null:'Depuis le début de l\'accident : '+dur(s.t-c.fired),
 evaluate(s,c){ const f=c.fired, T=x=>x==null?'non fait':dur(x-f), k=c.k;
  return [Cr('Soupape bloquée repérée et isolée en moins de 30 min',c.acts.porvIsol!=null&&c.acts.porvIsol-f<=1800,'Vous : '+T(c.acts.porvIsol)+' · TMI : 2 h 22'),
   Cr('Injection de sécurité laissée à plein débit tant que le primaire bout',k.isCut==null,(k.isCut!=null?'Réduite à '+T(k.isCut):'Jamais réduite')+' · TMI : réduite à 4 min 30'),
   Cr('Vannes ASG trouvées et ouvertes en moins de 10 min',c.acts.asgV!=null&&c.acts.asgV-f<=600,'Vous : '+T(c.acts.asgV)+' · TMI : 8 min'),
   Cr('Pompes primaires pas arrêtées au pire moment, circuit déjà très vidé',k.pmpCut==null||k.pmpCutA<0.3,(k.pmpCut!=null?'Arrêt à '+T(k.pmpCut)+', vapeur '+fmt(k.pmpCutA*100,0)+' % du circuit':'Gardées')+' · TMI : arrêtées à 1 h 14 et 1 h 40, circuit à moitié vapeur'),
   Cr('Cœur toujours sous l\'eau',!(k.maxUnc>0),k.uncT!=null?'Dénoyé à '+T(k.uncT)+' · TMI : vers 2 h':'TMI : dénoyé vers 2 h'),
   Cr('Gaines sous 1 204 °C',s.TgMax<=1204,'Maximum '+fmt(s.TgMax,0)+' °C')]; },
 debrief(s,c){ const f=c.fired, k=c.k, T=x=>x==null?'—':dur(x-f);
  const fin=s.coreDmg>=3?['Fusion partielle','Une partie du combustible a fondu ('+fmt(s.fondu*100,0)+' %), '+fmt(s.H2,0)+' kg d\'hydrogène produits. C\'est ce qui est arrivé à TMI-2.']
   :s.coreDmg>=1?['Cœur endommagé','Les gaines ont dépassé '+fmt(s.TgMax,0)+' °C et se sont oxydées ('+fmt(s.H2,0)+' kg d\'hydrogène), sans fusion du combustible.']
   :k.satT!=null?['Petite brèche maîtrisée','Le primaire a bouilli, mais le cœur est resté refroidi.']
   :['Arrêt propre','La fuite a été arrêtée avant que le primaire ne bouille.'];
  const rows=[['Primaire à saturation',T(k.satT),'6 min'],['Soupape isolée',T(c.acts.porvIsol),'2 h 22'],['Injection de sécurité réduite',T(k.isCut),'4 min 30'],['Vannes ASG ouvertes',T(c.acts.asgV),'8 min'],['Disque du réservoir de décharge rompu',T(k.burstT),'15 min'],['Pompes primaires arrêtées',T(k.pmpCut),'1 h 14'],['Cœur dénoyé',T(k.uncT),'vers 2 h']];
  return '<h3>État final : '+fin[0]+'</h3><p>'+fin[1]+'</p>'+chainHtml(c,true)+'<h3>Vous et l\'équipe de 1979</h3><table class="kv"><tr><td></td><td class="v">Vous</td><td class="v">TMI</td></tr>'+rows.map(r=>'<tr><td>'+r[0]+'</td><td class="v">'+r[1]+'</td><td class="v">'+r[2]+'</td></tr>').join('')+'</table>'
   +'<h3>Pourquoi l\'équipe de 1979 n\'a pas trouvé</h3><ul><li><b>Un voyant qui ment</b> : la lampe de la soupape montrait l\'ordre « fermer », pas la position réelle.</li><li><b>Un niveau trompeur</b> : la vapeur formée dans la cuve poussait l\'eau dans le pressuriseur. Son niveau montait pendant que le circuit se vidait.</li><li><b>Une règle apprise à contresens</b> : « ne jamais laisser le pressuriseur devenir plein ». Réduire l\'injection était le bon réflexe pour un autre accident.</li><li><b>L\'information utile manquait</b> : pas de marge à la saturation ni de niveau cuve, plus de cent alarmes en quelques minutes, une imprimante d\'alarmes en retard de plusieurs heures.</li><li><b>Le retour d\'expérience n\'est pas arrivé</b> : la même soupape s\'était bloquée à Davis-Besse en 1977.</li><li><b>Les pompes primaires arrêtées</b> parce qu\'elles vibraient : elles brassaient un mélange eau-vapeur qui refroidissait encore le cœur. Arrêtées tôt, circuit encore plein d\'eau, elles n\'auraient rien découvert ; arrêtées tard, la vapeur s\'est séparée de l\'eau d\'un coup. Depuis, les procédures font arrêter les pompes <b>tôt, sur un critère</b> (marge à la saturation perdue ou pression basse avec l\'injection en service), jamais tard au hasard des vibrations.</li></ul>'
   +'<h3>Ce qui a changé après</h3><p>Voyants de position réelle des vannes, indicateur de marge à la saturation, panneaux de sûreté, simulateurs pleine échelle. En France : l\'<b>approche par états</b> (on conduit sur l\'état physique de la tranche, sans avoir à deviner l\'événement) et un ingénieur sûreté en salle de commande.</p>'; },
 expected:"Signature à reconnaître : pression qui baisse <b>et</b> niveau pressuriseur qui monte, température haute sur la ligne de décharge, réservoir de décharge qui se remplit. C'est une brèche en tête du pressuriseur, même si le voyant de la soupape dit « fermée ». Il faut fermer la vanne d'isolement de la soupape, laisser l'injection de sécurité à plein débit (un pressuriseur plein n'est pas un danger quand le primaire bout), ouvrir les vannes ASG pour réalimenter les GV, et garder les pompes primaires tant qu'elles tournent : le mélange eau-vapeur refroidit encore le cœur, et les arrêter tard, circuit déjà vidé, le découvrirait d'un coup. Les procédures écrites après TMI les font arrêter tôt, sur un critère, quand le circuit contient encore beaucoup d'eau ; le scénario, joué avec les règles de 1979, demande seulement de ne pas les arrêter au pire moment.",
 d:"Un circuit qui perd de l'eau par le haut du pressuriseur se met à bouillir. Les bulles poussent l'eau dans le pressuriseur, qui paraît plein alors que le circuit se vide. À TMI, l'équipe a cru le circuit trop plein et a coupé l'eau de secours : le cœur s'est découvert."},
{id:'myst',kind:'alea',title:'Aléa mystère',desc:'Un aléa tiré au hasard, sans indication préalable.',diff:3,speed:1,init:P100},
{id:'libre',kind:'libre',title:'Pilotage libre à 100 %',desc:'Tranche à pleine puissance, sans objectif imposé.',diff:0,speed:1,init:P100},
{id:'libre0',kind:'libre',title:'Pilotage libre à l\'arrêt à chaud',desc:'Réacteur sous-critique, à vous de démarrer.',diff:0,speed:5,init:{P:0,critR:170,R:0,G:'cal',SD:225,coupled:false,xe:0,modeR:'man',modeG:'man'}},
];
/* ================= TMI : chaîne des événements et de leurs conséquences ================= */
/* chaque maillon s'affiche au moment où il se produit : ce qui arrive, puis ce que ça entraîne */
const TMI_CHAIN=[
 {id:'tpa',w:()=>true,e:"Les deux turbopompes alimentaires (TPA) s'arrêtent.",q:"Plus aucune eau n'entre dans les générateurs de vapeur, alors que la vapeur continue de partir : le niveau des GV chute vite."},
 {id:'asg',w:s=>s.asg&&!s.asgV,e:"Les pompes de secours ASG démarrent automatiquement…",q:"…mais leurs vannes sont restées fermées après un essai : aucune eau n'arrive. Les GV continuent de se vider, ils ne refroidissent presque plus le primaire."},
 {id:'chaud',w:(s,c,k)=>s.Ppzr>k.p0+2,e:"Les GV n'évacuent plus la chaleur du primaire.",q:"L'eau du primaire chauffe et se dilate : la pression du pressuriseur monte."},
 {id:'aar',w:s=>s.tripped,e:s=>"Arrêt automatique du réacteur"+(s.tripCause?" ("+s.tripCause+")":"")+".",q:"Les grappes chutent, la fission s'arrête. Reste la puissance résiduelle, quelques % de la puissance, qu'il faut toujours évacuer."},
 {id:'porv',w:s=>s.porvStuck,e:"Au pic de pression, la soupape SEBIM en tête du pressuriseur s'ouvre. L'ordre de fermeture part, mais elle reste bloquée ouverte.",q:s=>"Une brèche est ouverte en haut du primaire : la vapeur file vers le réservoir de décharge et la pression baisse."+(s.era79?" En salle de 1979, le voyant de la soupape indique « fermée » : il montre l'ordre envoyé, pas la position réelle.":"")},
 {id:'is',w:s=>s.is,e:"La pression passe sous le seuil d'injection de sécurité.",q:"L'IS envoie de l'eau borée dans le primaire : c'est elle qui compense la fuite et garde le cœur sous l'eau."},
 {id:'asgok',w:(s,c)=>c.acts.asgV!=null,e:"Vannes ASG ouvertes.",q:"Les GV sont réalimentés et évacuent de nouveau la chaleur. À TMI, il a fallu 8 minutes pour s'en apercevoir."},
 {id:'sat',w:s=>s.sat,e:"La pression a tant baissé que l'eau du primaire atteint sa température d'ébullition : le primaire bout.",q:"Les bulles prennent de la place et poussent l'eau dans le pressuriseur : son niveau monte alors que le circuit se vide. C'est le piège de TMI."},
 {id:'iscut',w:(s,c,k)=>k.isCut!=null,e:"Débit d'injection de sécurité réduit, comme à TMI pour ne pas « remplir » le pressuriseur.",q:"Il entre moins d'eau qu'il n'en sort par la soupape : le circuit se vide plus vite."},
 {id:'rdp',w:s=>s.rdpBurst,e:"Le réservoir de décharge du pressuriseur est plein : son disque de rupture cède.",q:"L'eau du primaire se déverse dans l'enceinte : pression et activité de l'enceinte montent."},
 {id:'vib',w:s=>s.vib>0.3,e:"Les pompes primaires vibrent.",q:"Elles brassent un mélange d'eau et de vapeur. Ce mélange refroidit encore le cœur : les arrêter maintenant, circuit déjà riche en vapeur, serait le pire moment."},
 {id:'pmp',w:(s,c,k)=>k.pmpCut!=null,e:"Pompes primaires arrêtées.",q:"L'eau et la vapeur se séparent : la vapeur s'accumule en haut de la cuve et le haut du cœur commence à se découvrir."},
 {id:'isol',w:(s,c)=>c.acts.porvIsol!=null,e:"Vanne d'isolement de la soupape fermée.",q:"La brèche est fermée : l'IS remplit le circuit et la pression remonte. À TMI, ce geste n'est venu qu'au bout de 2 h 22."},
 {id:'unc',w:(s,c,k)=>k.uncT!=null,e:"Le cœur est dénoyé.",q:"Sans eau autour, les gaines dépassent 1 000 °C, s'oxydent et produisent de l'hydrogène."},
 {id:'fus',w:(s,c,k)=>k.dmgT!=null,e:"Une partie du combustible fond.",q:"C'est l'état final de TMI-2 : près de la moitié du cœur a fondu, mais la cuve et l'enceinte ont tenu."}];
const chTxt=(x,s)=>typeof x==='function'?x(s):x;
function tmiChain(s,c){ const k=c.k; if(!k.chain) k.chain=[];
  for(const L of TMI_CHAIN){ if(k.chain.some(x=>x.id===L.id)) continue; let ok=false; try{ ok=L.w(s,c,k); }catch(e){}
   if(ok){ const it={id:L.id,t:s.t,e:chTxt(L.e,s),q:chTxt(L.q,s)}; k.chain.push(it); c.dirty=true; if(typeof onChain==='function') onChain(it); } } }
function chainHtml(c,full){ const L=(c.k.chain||[]); if(!L.length) return '';
  return '<div class="chain"><div class="chh">Chaîne des événements</div><ol>'+L.slice().reverse().slice(0,full?99:4).map((x,i)=>'<li'+(i===0?' class="new"':'')+'><span class="cht">'+dur(x.t-c.fired)+'</span><b>'+x.e+'</b><span class="chq">'+x.q+'</span></li>').join('')+'</ol></div>'; }

const ALEA_IDS=['tpa','ilot','drop','spray','leak','are','dil','gmpp','mdte','dgko','lhb'];
const byId=id=>SCN.find(x=>x.id===id);

